INSERT INTO `b_form` VALUES (1,'2026-05-18 11:27:16','Оформление заказа','aspro_allcorp2_order_page_s1','Отправить',300,NULL,NULL,'N','Заполните простую форму и наши менеджеры свяжуться с вами, ответят на любые вопросы и подготовят счет на оплату','text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_order_page_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(2,'2026-05-18 11:27:16','Написать директору','aspro_allcorp2_director_s1','Отправить',300,NULL,NULL,'N','Если у вас возникли вопросы по поводу работы наших сотрудников или компании в целом, а также если вы хотите сказать слова благодарности, напишите сообщение и оно придет директору лично','text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_director_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(3,'2026-05-18 11:27:16','Заказать продукт','aspro_allcorp2_order_product_s1','Отправить',300,NULL,NULL,'N',NULL,'text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_order_product_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(4,'2026-05-18 11:27:16','Заказать проект','aspro_allcorp2_order_project_s1','Отправить',300,NULL,NULL,'N',NULL,'text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_order_project_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(5,'2026-05-18 11:27:16','Заказать услугу','aspro_allcorp2_order_services_s1','Отправить',300,NULL,NULL,'N',NULL,'text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_order_services_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(6,'2026-05-18 11:27:16','Заказать курс','aspro_allcorp2_order_study_s1','Отправить',300,NULL,NULL,'N',NULL,'text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_order_study_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(7,'2026-05-18 11:27:16','Задать вопрос','aspro_allcorp2_question_s1','Отправить',300,NULL,NULL,'N','Менеджеры компании с радостью ответят на ваши вопросы и произведут расчет стоимости услуг и подготовят индивидуальное коммерческое предложение. ','text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_question_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(8,'2026-05-18 11:27:17','Резюме','aspro_allcorp2_resume_s1','Отправить',300,NULL,NULL,'N',NULL,'text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_resume_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(9,'2026-05-18 11:27:17','Заказать звонок','aspro_allcorp2_callback_s1','Отправить',300,NULL,NULL,'N','Представьтесь, мы вам перезвоним.','text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_callback_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(10,'2026-05-18 11:27:17','Написать сотруднику','aspro_allcorp2_callstaff_s1','Отправить',300,NULL,NULL,'N','','text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_callstaff_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL),(11,'2026-05-18 11:27:17','Оставить отзыв','aspro_allcorp2_feedback_s1','Отправить',300,NULL,NULL,'N','','text',NULL,'Y',NULL,'FORM_FILLING_aspro_allcorp2_feedback_s1',NULL,NULL,NULL,NULL,NULL,'N',0,0,NULL,'form','',NULL);
