INSERT INTO `b_iblock_section` VALUES (1,'2026-05-14 16:00:27',1,'2026-05-14 16:00:27',1,2,NULL,'Y','Y',100,'Мягкая мебель',1,1,2,1,'Диваны, кресла и прочая мягкая мебель','html','МЯГКАЯ МЕБЕЛЬ\r\nДИВАНЫ, КРЕСЛА И ПРОЧАЯ МЯГКАЯ МЕБЕЛЬ',NULL,'2',NULL,NULL,NULL),(2,'2026-05-14 16:00:27',1,'2026-05-14 16:00:27',1,2,NULL,'Y','Y',200,'Офисная мебель',2,3,4,1,'Диваны, столы, стулья','html','ОФИСНАЯ МЕБЕЛЬ\r\nДИВАНЫ, СТОЛЫ, СТУЛЬЯ',NULL,'3',NULL,NULL,NULL),(3,'2026-05-14 16:00:27',1,'2026-05-14 16:00:27',1,2,NULL,'Y','Y',300,'Мебель для кухни',3,5,6,1,'Полки, ящики, столы и стулья','html','МЕБЕЛЬ ДЛЯ КУХНИ\r\nПОЛКИ, ЯЩИКИ, СТОЛЫ И СТУЛЬЯ',NULL,'4',NULL,NULL,NULL),(4,'2026-05-14 16:00:27',1,'2026-05-14 16:00:27',1,2,NULL,'Y','Y',400,'Детская мебель',4,7,8,1,'Кровати, стулья, мягкая детская мебель','html','ДЕТСКАЯ МЕБЕЛЬ\r\nКРОВАТИ, СТУЛЬЯ, МЯГКАЯ ДЕТСКАЯ МЕБЕЛЬ',NULL,'5',NULL,NULL,NULL),(5,'2026-05-18 11:26:48',1,'2026-05-18 11:26:48',1,5,NULL,'Y','Y',400,'Центр',NULL,1,4,1,NULL,'text','ЦЕНТР\r\n',NULL,'338',NULL,NULL,NULL),(6,'2026-05-18 11:26:48',1,'2026-05-18 11:26:48',1,5,5,'Y','Y',500,'Московская область',NULL,2,3,2,NULL,'text','МОСКОВСКАЯ ОБЛАСТЬ\r\n',NULL,'334',NULL,NULL,NULL),(7,'2026-05-18 11:26:48',1,'2026-05-18 11:26:48',1,5,NULL,'Y','Y',500,'Урал',NULL,5,10,1,NULL,'text','УРАЛ\r\n',NULL,'337',NULL,NULL,NULL),(8,'2026-05-18 11:26:48',1,'2026-05-18 11:26:48',1,5,7,'Y','Y',500,'Свердловская область',NULL,6,7,2,NULL,'text','СВЕРДЛОВСКАЯ ОБЛАСТЬ\r\n',NULL,'336',NULL,NULL,NULL),(9,'2026-05-18 11:26:48',1,'2026-05-18 11:26:48',1,5,7,'Y','Y',500,'Челябинская область',NULL,8,9,2,NULL,'text','ЧЕЛЯБИНСКАЯ ОБЛАСТЬ\r\n',NULL,'335',NULL,NULL,NULL),(10,'2026-06-18 11:49:52',1,'2026-05-18 11:26:54',1,15,NULL,'Y','Y',300,'Руководители',NULL,1,2,1,'<p>\r\nРуководители компании «РАЛМАСТЕР» — это специалисты с многолетним опытом в сфере производства и монтажа металлоконструкций. Они формируют стратегию развития компании, контролируют качество выполнения работ и совершенствуют внутренние технологические процессы.\r\n</p>\r\n<p>\r\nГлубокое понимание инженерных решений, производственных стандартов и требований безопасности позволяет руководству эффективно координировать работу всех подразделений — от проектирования до монтажа. Опыт и профессионализм руководителей помогают команде поддерживать высокий уровень качества и успешно реализовывать проекты любой сложности.\r\n</p>','html','РУКОВОДИТЕЛИ\r\nРУКОВОДИТЕЛИ КОМПАНИИ «РАЛМАСТЕР» — ЭТО \r\nСПЕЦИАЛИСТЫ С МНОГОЛЕТНИМ ОПЫТОМ В СФЕРЕ ПРОИЗВОДСТВА И МОНТАЖА МЕТАЛЛОКОНСТРУКЦИЙ. ОНИ ФОРМИРУЮТ СТРАТЕГИЮ РАЗВИТИЯ КОМПАНИИ, КОНТРОЛИРУЮТ КАЧЕСТВО ВЫПОЛНЕНИЯ РАБОТ И СОВЕРШЕНСТВУЮТ ВНУТРЕННИЕ ТЕХНОЛОГИЧЕСКИЕ ПРОЦЕССЫ. \r\n\r\nГЛУБОКОЕ ПОНИМАНИЕ ИНЖЕНЕРНЫХ РЕШЕНИЙ, \r\nПРОИЗВОДСТВЕННЫХ СТАНДАРТОВ И ТРЕБОВАНИЙ БЕЗОПАСНОСТИ ПОЗВОЛЯЕТ РУКОВОДСТВУ ЭФФЕКТИВНО КООРДИНИРОВАТЬ РАБОТУ ВСЕХ ПОДРАЗДЕЛЕНИЙ — ОТ ПРОЕКТИРОВАНИЯ ДО МОНТАЖА. ОПЫТ И ПРОФЕССИОНАЛИЗМ РУКОВОДИТЕЛЕЙ ПОМОГАЮТ КОМАНДЕ ПОДДЕРЖИВАТЬ ВЫСОКИЙ УРОВЕНЬ КАЧЕСТВА И УСПЕШНО РЕАЛИЗОВЫВАТЬ ПРОЕКТЫ ЛЮБОЙ СЛОЖНОСТИ.','rukovoditeli','13',NULL,NULL,NULL),(11,'2026-06-18 11:50:26',1,'2026-05-18 11:26:54',1,15,NULL,'Y','Y',400,'Менеджеры',NULL,3,4,1,'<p>Специалисты отдела продаж и сопровождения проектов — это первое звено взаимодействия с нашей компанией. Менеджеры «РАЛМАСТЕР» подробно консультируют по услугам, помогают подобрать оптимальное решение с учётом задач и бюджета, ориентируют по срокам и стоимости работ.\r\n</p>\r\n<p>\r\nОни разъяснят особенности материалов, этапы производства и монтажа, подготовят коммерческое предложение и подробно расскажут об условиях договора. Если вы не уверены, какой формат металлоконструкции подойдёт именно для вашего объекта, наши менеджеры помогут принять взвешенное и технически обоснованное решение.\r\n</p>','html','МЕНЕДЖЕРЫ\r\nСПЕЦИАЛИСТЫ ОТДЕЛА ПРОДАЖ И СОПРОВОЖДЕНИЯ \r\nПРОЕКТОВ — ЭТО ПЕРВОЕ ЗВЕНО ВЗАИМОДЕЙСТВИЯ С НАШЕЙ КОМПАНИЕЙ. МЕНЕДЖЕРЫ «РАЛМАСТЕР» ПОДРОБНО КОНСУЛЬТИРУЮТ ПО УСЛУГАМ, ПОМОГАЮТ ПОДОБРАТЬ ОПТИМАЛЬНОЕ РЕШЕНИЕ С УЧЁТОМ ЗАДАЧ И БЮДЖЕТА, ОРИЕНТИРУЮТ ПО СРОКАМ И СТОИМОСТИ РАБОТ. \r\n\r\nОНИ РАЗЪЯСНЯТ ОСОБЕННОСТИ МАТЕРИАЛОВ, \r\nЭТАПЫ ПРОИЗВОДСТВА И МОНТАЖА, ПОДГОТОВЯТ КОММЕРЧЕСКОЕ ПРЕДЛОЖЕНИЕ И ПОДРОБНО РАССКАЖУТ ОБ УСЛОВИЯХ ДОГОВОРА. ЕСЛИ ВЫ НЕ УВЕРЕНЫ, КАКОЙ ФОРМАТ МЕТАЛЛОКОНСТРУКЦИИ ПОДОЙДЁТ ИМЕННО ДЛЯ ВАШЕГО ОБЪЕКТА, НАШИ МЕНЕДЖЕРЫ ПОМОГУТ ПРИНЯТЬ ВЗВЕШЕННОЕ И ТЕХНИЧЕСКИ ОБОСНОВАННОЕ РЕШЕНИЕ.','menedzhery','12',NULL,NULL,NULL),(12,'2026-06-18 11:37:21',1,'2026-05-18 11:26:54',1,15,NULL,'N','N',500,'Отдел проектов',NULL,5,6,1,'Проект-менеджеры всегда помогут клиентам в организации работы на объекте. Они отвечают за координацию инженеров, отчетную документацию, напоминания о сервисном обслуживании. Если у вас возникли вопросы в ходе работы инженеров или других сотрудников – смело обращайтесь в отдел проектов.','html','ОТДЕЛ ПРОЕКТОВ\r\nПРОЕКТ-МЕНЕДЖЕРЫ ВСЕГДА ПОМОГУТ КЛИЕНТАМ \r\nВ ОРГАНИЗАЦИИ РАБОТЫ НА ОБЪЕКТЕ. ОНИ ОТВЕЧАЮТ ЗА КООРДИНАЦИЮ ИНЖЕНЕРОВ, ОТЧЕТНУЮ ДОКУМЕНТАЦИЮ, НАПОМИНАНИЯ О СЕРВИСНОМ ОБСЛУЖИВАНИИ. ЕСЛИ У ВАС ВОЗНИКЛИ ВОПРОСЫ В ХОДЕ РАБОТЫ ИНЖЕНЕРОВ ИЛИ ДРУГИХ СОТРУДНИКОВ – СМЕЛО ОБРАЩАЙТЕСЬ В ОТДЕЛ ПРОЕКТОВ.','otdel-proektov','21',NULL,NULL,NULL),(13,'2026-05-18 11:26:54',1,'2026-05-18 11:26:54',1,16,NULL,'Y','Y',100,'Отдел продаж',NULL,1,2,1,NULL,'text','ОТДЕЛ ПРОДАЖ\r\n',NULL,'14',NULL,NULL,NULL),(14,'2026-05-18 11:26:54',1,'2026-05-18 11:26:54',1,16,NULL,'Y','Y',200,'Рабочий персонал',NULL,3,4,1,NULL,'text','РАБОЧИЙ ПЕРСОНАЛ\r\n','rabochiy-personal','15',NULL,NULL,NULL),(15,'2026-05-18 11:26:55',1,'2026-05-18 11:26:55',1,17,NULL,'Y','Y',400,'Общие вопросы',NULL,1,2,1,NULL,'text','ОБЩИЕ ВОПРОСЫ\r\n','obshchie-voprosy','2',NULL,NULL,NULL),(16,'2026-05-18 11:26:55',1,'2026-05-18 11:26:55',1,17,NULL,'Y','Y',500,'Вопросы по услугам',NULL,3,4,1,NULL,'text','ВОПРОСЫ ПО УСЛУГАМ\r\n','voprosy-po-uslugam','3',NULL,NULL,NULL),(17,'2026-05-18 11:26:56',1,'2026-05-18 11:26:56',1,18,NULL,'Y','Y',100,'Сертификаты',NULL,1,2,1,'Сертификат соответствия &ndash; документ, подтверждающий соответствие продукции требованиям качества и безопасности, установленными для нее действующими стандартами и правилами.','html','СЕРТИФИКАТЫ\r\nСЕРТИФИКАТ СООТВЕТСТВИЯ &NDASH; ДОКУМЕНТ, \r\nПОДТВЕРЖДАЮЩИЙ СООТВЕТСТВИЕ ПРОДУКЦИИ ТРЕБОВАНИЯМ КАЧЕСТВА И БЕЗОПАСНОСТИ, УСТАНОВЛЕННЫМИ ДЛЯ НЕЕ ДЕЙСТВУЮЩИМИ СТАНДАРТАМИ И ПРАВИЛАМИ.','sertifikaty-na-produktsiyu','9',NULL,NULL,NULL),(18,'2026-05-18 11:26:56',1,'2026-05-18 11:26:56',1,18,NULL,'Y','Y',200,'Лицензии',NULL,3,4,1,'Лицензиями на оказание услуг мы подтверждаем законность осуществляемой деятельности и качество выполняемой работы.','html','ЛИЦЕНЗИИ\r\nЛИЦЕНЗИЯМИ НА ОКАЗАНИЕ УСЛУГ МЫ ПОДТВЕРЖДАЕМ \r\nЗАКОННОСТЬ ОСУЩЕСТВЛЯЕМОЙ ДЕЯТЕЛЬНОСТИ И КАЧЕСТВО ВЫПОЛНЯЕМОЙ РАБОТЫ.','litsenzii','8',NULL,NULL,NULL),(19,'2026-05-18 11:26:57',1,'2026-05-18 11:26:57',1,19,NULL,'Y','Y',500,'События',NULL,1,2,1,'Оперативные информационные сообщения, которые представляют политический, социальный или экономический интерес для аудитории в своей свежести, то есть сообщение о событиях произошедших недавно или происходящих в данный момент. Как правило, новости на телевидении и радио передаются несколько раз в день, начинаются в начале часа и длятся от двух минут до получаса. Новости обычно бывают из таких областей, как политика, экономика, наука, культура, спорт, с прогнозом погоды в заключении. Западной традицией предполагается, что новости должны быть изложены максимально нейтрально и объективно и отдельно от комментариев. Выбор новостей для подборки осуществляется редакцией.','html','СОБЫТИЯ\r\nОПЕРАТИВНЫЕ ИНФОРМАЦИОННЫЕ СООБЩЕНИЯ, \r\nКОТОРЫЕ ПРЕДСТАВЛЯЮТ ПОЛИТИЧЕСКИЙ, СОЦИАЛЬНЫЙ ИЛИ ЭКОНОМИЧЕСКИЙ ИНТЕРЕС ДЛЯ АУДИТОРИИ В СВОЕЙ СВЕЖЕСТИ, ТО ЕСТЬ СООБЩЕНИЕ О СОБЫТИЯХ ПРОИЗОШЕДШИХ НЕДАВНО ИЛИ ПРОИСХОДЯЩИХ В ДАННЫЙ МОМЕНТ. КАК ПРАВИЛО, НОВОСТИ НА ТЕЛЕВИДЕНИИ И РАДИО ПЕРЕДАЮТСЯ НЕСКОЛЬКО РАЗ В ДЕНЬ, НАЧИНАЮТСЯ В НАЧАЛЕ ЧАСА И ДЛЯТСЯ ОТ ДВУХ МИНУТ ДО ПОЛУЧАСА. НОВОСТИ ОБЫЧНО БЫВАЮТ ИЗ ТАКИХ ОБЛАСТЕЙ, КАК ПОЛИТИКА, ЭКОНОМИКА, НАУКА, КУЛЬТУРА, СПОРТ, С ПРОГНОЗОМ ПОГОДЫ В ЗАКЛЮЧЕНИИ. ЗАПАДНОЙ ТРАДИЦИЕЙ ПРЕДПОЛАГАЕТСЯ, ЧТО НОВОСТИ ДОЛЖНЫ БЫТЬ ИЗЛОЖЕНЫ МАКСИМАЛЬНО НЕЙТРАЛЬНО И ОБЪЕКТИВНО И ОТДЕЛЬНО ОТ КОММЕНТАРИЕВ. ВЫБОР НОВОСТЕЙ ДЛЯ ПОДБОРКИ ОСУЩЕСТВЛЯЕТСЯ РЕДАКЦИЕЙ.',NULL,'16',NULL,NULL,NULL),(20,'2026-05-18 11:26:57',1,'2026-05-18 11:26:57',1,19,NULL,'Y','Y',500,'Специальные предложения',NULL,3,4,1,NULL,'text','СПЕЦИАЛЬНЫЕ ПРЕДЛОЖЕНИЯ\r\n',NULL,'17',NULL,NULL,NULL),(21,'2026-06-17 17:01:30',1,'2026-05-18 11:26:58',1,20,NULL,'N','N',100,'Производители',NULL,1,2,1,NULL,'text','ПРОИЗВОДИТЕЛИ\r\n','proizvoditeli','493',NULL,NULL,NULL),(22,'2026-06-17 17:01:30',1,'2026-05-18 11:26:58',1,20,NULL,'N','N',200,'Разработчики',NULL,3,4,1,'Сотрудничаем с лидерами разработки готовых решений на 1С-Битрикс, систем управления веб-проектами и корпоративными порталами. Подбираем инструменты под конкретные задачи бизнеса, интегрируем их в процессы так, чтобы у вас не болела голова.<br>\n <br>\n Среди решений, с которыми мы работаем:&nbsp;<br>\n<ul>\n	<li>готовые интернет-магазины и корпоративные сайты для быстрого запуска проекта в Интернете</li>\n	<li>CRM-системы и системы управления проектами для того, чтобы ваши бизнес-процессы были отлаженными, как часы</li>\n	<li>надежный хостинг-провайдер, который никогда не подведет.&nbsp;</li>\n</ul>','html','РАЗРАБОТЧИКИ\r\nСОТРУДНИЧАЕМ С ЛИДЕРАМИ РАЗРАБОТКИ ГОТОВЫХ \r\nРЕШЕНИЙ НА 1С-БИТРИКС, СИСТЕМ УПРАВЛЕНИЯ ВЕБ-ПРОЕКТАМИ И КОРПОРАТИВНЫМИ ПОРТАЛАМИ. ПОДБИРАЕМ ИНСТРУМЕНТЫ ПОД КОНКРЕТНЫЕ ЗАДАЧИ БИЗНЕСА, ИНТЕГРИРУЕМ ИХ В ПРОЦЕССЫ ТАК, ЧТОБЫ У ВАС НЕ БОЛЕЛА ГОЛОВА.\r\n\r\nСРЕДИ РЕШЕНИЙ, С КОТОРЫМИ МЫ РАБОТАЕМ:&NBSP;\r\n\r\n\r\n- ГОТОВЫЕ ИНТЕРНЕТ-МАГАЗИНЫ И КОРПОРАТИВНЫЕ \r\nСАЙТЫ ДЛЯ БЫСТРОГО ЗАПУСКА ПРОЕКТА В ИНТЕРНЕТЕ \r\n- CRM-СИСТЕМЫ И СИСТЕМЫ УПРАВЛЕНИЯ ПРОЕКТАМИ \r\nДЛЯ ТОГО, ЧТОБЫ ВАШИ БИЗНЕС-ПРОЦЕССЫ БЫЛИ ОТЛАЖЕННЫМИ, КАК ЧАСЫ \r\n- НАДЕЖНЫЙ ХОСТИНГ-ПРОВАЙДЕР, КОТОРЫЙ НИКОГДА \r\nНЕ ПОДВЕДЕТ.&NBSP;',NULL,'11',NULL,NULL,NULL),(23,'2026-06-17 17:01:30',1,'2026-05-18 11:26:58',1,20,NULL,'N','N',300,'Другие решения компании Аспро',NULL,5,6,1,NULL,'text','ДРУГИЕ РЕШЕНИЯ КОМПАНИИ АСПРО\r\n',NULL,'10',NULL,NULL,NULL),(24,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,NULL,'Y','Y',50,'Челябинская область',NULL,1,8,1,NULL,'text','ЧЕЛЯБИНСКАЯ ОБЛАСТЬ\r\n',NULL,'184',NULL,NULL,NULL),(25,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,24,'Y','Y',50,'Челябинск',NULL,2,3,2,NULL,'text','ЧЕЛЯБИНСК\r\n',NULL,'188',NULL,NULL,NULL),(26,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,24,'Y','Y',500,'Магнитогорск',NULL,4,5,2,NULL,'text','МАГНИТОГОРСК\r\n',NULL,'189',NULL,NULL,NULL),(27,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,24,'Y','Y',500,'Миасс',NULL,6,7,2,NULL,'text','МИАСС\r\n',NULL,'190',NULL,NULL,NULL),(28,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,NULL,'Y','Y',500,'Московская область',NULL,9,14,1,NULL,'text','МОСКОВСКАЯ ОБЛАСТЬ\r\n',NULL,'182',NULL,NULL,NULL),(29,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,28,'Y','Y',500,'Клин',NULL,10,11,2,NULL,'text','КЛИН\r\n',NULL,'186',NULL,NULL,NULL),(30,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,28,'Y','Y',500,'Москва',NULL,12,13,2,NULL,'text','МОСКВА\r\n',NULL,'185',NULL,NULL,NULL),(31,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,NULL,'Y','Y',500,'Свердловская область',NULL,15,18,1,NULL,'text','СВЕРДЛОВСКАЯ ОБЛАСТЬ\r\n',NULL,'183',NULL,NULL,NULL),(32,'2026-05-18 11:27:04',1,'2026-05-18 11:27:04',1,33,31,'Y','Y',500,'Екатеринбург',NULL,16,17,2,NULL,'text','ЕКАТЕРИНБУРГ\r\n',NULL,'187',NULL,NULL,NULL),(33,'2026-05-18 11:27:05',1,'2026-05-18 11:27:05',1,34,NULL,'Y','Y',500,'Новинки',NULL,1,2,1,NULL,'text','НОВИНКИ\r\n','novinki','481',NULL,NULL,NULL),(34,'2026-05-18 11:27:05',1,'2026-05-18 11:27:05',1,34,NULL,'Y','Y',500,'Общие',NULL,3,4,1,'Оперативные информационные сообщения, которые представляют политический, социальный или экономический интерес для аудитории в своей свежести, то есть сообщение о событиях произошедших недавно или происходящих в данный момент. Как правило, новости на телевидении и радио передаются несколько раз в день, начинаются в начале часа и длятся от двух минут до получаса. Новости обычно бывают из таких областей, как политика, экономика, наука, культура, спорт, с прогнозом погоды в заключении. Западной традицией предполагается, что новости должны быть изложены максимально нейтрально и объективно и отдельно от комментариев. Выбор новостей для подборки осуществляется редакцией.','html','ОБЩИЕ\r\nОПЕРАТИВНЫЕ ИНФОРМАЦИОННЫЕ СООБЩЕНИЯ, \r\nКОТОРЫЕ ПРЕДСТАВЛЯЮТ ПОЛИТИЧЕСКИЙ, СОЦИАЛЬНЫЙ ИЛИ ЭКОНОМИЧЕСКИЙ ИНТЕРЕС ДЛЯ АУДИТОРИИ В СВОЕЙ СВЕЖЕСТИ, ТО ЕСТЬ СООБЩЕНИЕ О СОБЫТИЯХ ПРОИЗОШЕДШИХ НЕДАВНО ИЛИ ПРОИСХОДЯЩИХ В ДАННЫЙ МОМЕНТ. КАК ПРАВИЛО, НОВОСТИ НА ТЕЛЕВИДЕНИИ И РАДИО ПЕРЕДАЮТСЯ НЕСКОЛЬКО РАЗ В ДЕНЬ, НАЧИНАЮТСЯ В НАЧАЛЕ ЧАСА И ДЛЯТСЯ ОТ ДВУХ МИНУТ ДО ПОЛУЧАСА. НОВОСТИ ОБЫЧНО БЫВАЮТ ИЗ ТАКИХ ОБЛАСТЕЙ, КАК ПОЛИТИКА, ЭКОНОМИКА, НАУКА, КУЛЬТУРА, СПОРТ, С ПРОГНОЗОМ ПОГОДЫ В ЗАКЛЮЧЕНИИ. ЗАПАДНОЙ ТРАДИЦИЕЙ ПРЕДПОЛАГАЕТСЯ, ЧТО НОВОСТИ ДОЛЖНЫ БЫТЬ ИЗЛОЖЕНЫ МАКСИМАЛЬНО НЕЙТРАЛЬНО И ОБЪЕКТИВНО И ОТДЕЛЬНО ОТ КОММЕНТАРИЕВ. ВЫБОР НОВОСТЕЙ ДЛЯ ПОДБОРКИ ОСУЩЕСТВЛЯЕТСЯ РЕДАКЦИЕЙ.',NULL,'16',NULL,NULL,NULL),(35,'2026-05-18 11:27:06',1,'2026-05-18 11:27:06',1,35,NULL,'Y','Y',500,'Скидки',NULL,1,2,1,NULL,'text','СКИДКИ\r\n','aktsii','468',NULL,NULL,NULL),(36,'2026-05-18 11:27:06',1,'2026-05-18 11:27:06',1,35,NULL,'Y','Y',500,'События',NULL,3,4,1,NULL,'text','СОБЫТИЯ\r\n','novosti','469',NULL,NULL,NULL),(37,'2026-06-11 12:28:37',1,'2026-05-18 11:27:06',1,36,NULL,'N','N',500,'Автоматизация',NULL,1,2,1,NULL,'text','АВТОМАТИЗАЦИЯ\r\n','avtomatizatsiya','485',NULL,NULL,NULL),(38,'2026-06-11 12:28:37',1,'2026-05-18 11:27:06',1,36,NULL,'N','N',500,'Охранные системы',NULL,7,8,1,NULL,'text','ОХРАННЫЕ СИСТЕМЫ\r\n','okhrannye-sistemy','161',NULL,NULL,NULL),(39,'2026-06-11 12:28:37',1,'2026-05-18 11:27:06',1,36,NULL,'N','N',500,'Системы вентиляции',NULL,9,10,1,NULL,'text','СИСТЕМЫ ВЕНТИЛЯЦИИ\r\n','sistemy-ventilyatsii','444',NULL,NULL,NULL),(40,'2026-06-11 12:28:37',1,'2026-05-18 11:27:06',1,36,NULL,'N','N',500,'Строительство',NULL,11,12,1,NULL,'text','СТРОИТЕЛЬСТВО\r\n','stroitelstvo','486',NULL,NULL,NULL),(41,'2026-06-11 12:28:37',1,'2026-05-18 11:27:07',1,36,NULL,'N','N',500,'Электроосвещение',NULL,13,14,1,NULL,'text','ЭЛЕКТРООСВЕЩЕНИЕ\r\n','elektroosveshchenie','445',NULL,NULL,NULL),(42,'2026-06-16 14:30:59',1,'2026-05-18 11:27:07',1,37,NULL,'Y','Y',500,'Бизнес-советы',NULL,1,2,1,NULL,'text','БИЗНЕС-СОВЕТЫ\r\n','biznes-sovety','179',NULL,NULL,NULL),(43,'2026-06-16 14:27:17',1,'2026-05-18 11:27:07',1,37,NULL,'N','N',500,'Дизайн',NULL,3,4,1,NULL,'text','ДИЗАЙН\r\n','dizayn-interera','487',NULL,NULL,NULL),(44,'2026-06-16 14:27:17',1,'2026-05-18 11:27:07',1,37,NULL,'N','N',500,'Инженерные системы',NULL,5,6,1,NULL,'text','ИНЖЕНЕРНЫЕ СИСТЕМЫ\r\n','inzhenernye-sistemy','489',NULL,NULL,NULL),(45,'2026-06-16 14:27:17',1,'2026-05-18 11:27:07',1,37,NULL,'N','N',500,'Металлообработка',NULL,7,8,1,NULL,'text','МЕТАЛЛООБРАБОТКА\r\n','metalloobrabotka','488',NULL,NULL,NULL),(46,'2026-06-16 14:27:17',1,'2026-05-18 11:27:07',1,37,NULL,'N','N',500,'Повышение продаж',NULL,9,10,1,NULL,'text','ПОВЫШЕНИЕ ПРОДАЖ\r\n','povyshenie-prodazh','178',NULL,NULL,NULL),(47,'2026-06-16 14:27:17',1,'2026-05-18 11:27:07',1,37,NULL,'N','N',500,'Управление проектами',NULL,11,12,1,NULL,'text','УПРАВЛЕНИЕ ПРОЕКТАМИ\r\n','testovyy-razdel','175',NULL,NULL,NULL),(48,'2026-05-18 11:27:09',1,'2026-05-18 11:27:09',1,39,NULL,'Y','Y',500,'Английский язык для взрослых',303,1,2,1,'<p>\n	 Учет особенностей курсов английского для взрослых – важная составляющая деятельности преподавателей школы английского языка. Организация занятий в основном осуществляется в вечернее время (с18 до 20 часов) по желанию взрослых студентов. Слушатели курсов английского имеют непреодолимое желание обучаться у строгого и требовательного преподавателя по причине отсутствия самостоятельной мотивации к занятиям. Требования преподавателя вызовет определенный напряг у взрослых, следовательно, результат не заставит себя ждать. <br>\n <br>\n	 Взрослые люди имеют высокий уровень понимания необходимости владения иностранным языком. Осознание реального мотива изучения языка – серьезная помощь на занятиях. Причины самые разнообразные: иностранный нужен для работы, для поездки во время отпуска, для продолжения учебы, науки.\n</p>\n<ul>\n	<li>Наличие определенного уровня стеснительности при общении на занятиях, спровоцированное знанием заранее неправильного варианта, порождающего молчание вместо разговора. Между тем роль разговорной практики неоценима в овладении языком.</li>\n	<li>Отсутствие желания выполнять домашние задания. Нахождение ряда причин его невыполнения (дети, масса проблем, пробки). При том что уровень эффективности обучения иностранному языку имеет прямую зависимость от качества домашней подготовки.</li>\n	<li>Полное непринятие игровой формы в процессе обучения на курсах английского по причине серьезности вида взрослых. Тем не менее усвоение знаний в процессе игры осуществляется довольно оперативно и без всяких сложностей.</li>\n</ul>\n<p>\n</p>','html','АНГЛИЙСКИЙ ЯЗЫК ДЛЯ ВЗРОСЛЫХ\r\nУЧЕТ ОСОБЕННОСТЕЙ КУРСОВ АНГЛИЙСКОГО ДЛЯ \r\nВЗРОСЛЫХ – ВАЖНАЯ СОСТАВЛЯЮЩАЯ ДЕЯТЕЛЬНОСТИ ПРЕПОДАВАТЕЛЕЙ ШКОЛЫ АНГЛИЙСКОГО ЯЗЫКА. ОРГАНИЗАЦИЯ ЗАНЯТИЙ В ОСНОВНОМ ОСУЩЕСТВЛЯЕТСЯ В ВЕЧЕРНЕЕ ВРЕМЯ (С18 ДО 20 ЧАСОВ) ПО ЖЕЛАНИЮ ВЗРОСЛЫХ СТУДЕНТОВ. СЛУШАТЕЛИ КУРСОВ АНГЛИЙСКОГО ИМЕЮТ НЕПРЕОДОЛИМОЕ ЖЕЛАНИЕ ОБУЧАТЬСЯ У СТРОГОГО И ТРЕБОВАТЕЛЬНОГО ПРЕПОДАВАТЕЛЯ ПО ПРИЧИНЕ ОТСУТСТВИЯ САМОСТОЯТЕЛЬНОЙ МОТИВАЦИИ К ЗАНЯТИЯМ. ТРЕБОВАНИЯ ПРЕПОДАВАТЕЛЯ ВЫЗОВЕТ ОПРЕДЕЛЕННЫЙ НАПРЯГ У ВЗРОСЛЫХ, СЛЕДОВАТЕЛЬНО, РЕЗУЛЬТАТ НЕ ЗАСТАВИТ СЕБЯ ЖДАТЬ. \r\n\r\nВЗРОСЛЫЕ ЛЮДИ ИМЕЮТ ВЫСОКИЙ УРОВЕНЬ ПОНИМАНИЯ \r\nНЕОБХОДИМОСТИ ВЛАДЕНИЯ ИНОСТРАННЫМ ЯЗЫКОМ. ОСОЗНАНИЕ РЕАЛЬНОГО МОТИВА ИЗУЧЕНИЯ ЯЗЫКА – СЕРЬЕЗНАЯ ПОМОЩЬ НА ЗАНЯТИЯХ. ПРИЧИНЫ САМЫЕ РАЗНООБРАЗНЫЕ: ИНОСТРАННЫЙ НУЖЕН ДЛЯ РАБОТЫ, ДЛЯ ПОЕЗДКИ ВО ВРЕМЯ ОТПУСКА, ДЛЯ ПРОДОЛЖЕНИЯ УЧЕБЫ, НАУКИ. \r\n\r\n- НАЛИЧИЕ ОПРЕДЕЛЕННОГО УРОВНЯ СТЕСНИТЕЛЬНОСТИ \r\nПРИ ОБЩЕНИИ НА ЗАНЯТИЯХ, СПРОВОЦИРОВАННОЕ ЗНАНИЕМ ЗАРАНЕЕ НЕПРАВИЛЬНОГО ВАРИАНТА, ПОРОЖДАЮЩЕГО МОЛЧАНИЕ ВМЕСТО РАЗГОВОРА. МЕЖДУ ТЕМ РОЛЬ РАЗГОВОРНОЙ ПРАКТИКИ НЕОЦЕНИМА В ОВЛАДЕНИИ ЯЗЫКОМ. \r\n- ОТСУТСТВИЕ ЖЕЛАНИЯ ВЫПОЛНЯТЬ ДОМАШНИЕ \r\nЗАДАНИЯ. НАХОЖДЕНИЕ РЯДА ПРИЧИН ЕГО НЕВЫПОЛНЕНИЯ (ДЕТИ, МАССА ПРОБЛЕМ, ПРОБКИ). ПРИ ТОМ ЧТО УРОВЕНЬ ЭФФЕКТИВНОСТИ ОБУЧЕНИЯ ИНОСТРАННОМУ ЯЗЫКУ ИМЕЕТ ПРЯМУЮ ЗАВИСИМОСТЬ ОТ КАЧЕСТВА ДОМАШНЕЙ ПОДГОТОВКИ. \r\n- ПОЛНОЕ НЕПРИНЯТИЕ ИГРОВОЙ ФОРМЫ В ПРОЦЕССЕ \r\nОБУЧЕНИЯ НА КУРСАХ АНГЛИЙСКОГО ПО ПРИЧИНЕ СЕРЬЕЗНОСТИ ВИДА ВЗРОСЛЫХ. ТЕМ НЕ МЕНЕЕ УСВОЕНИЕ ЗНАНИЙ В ПРОЦЕССЕ ИГРЫ ОСУЩЕСТВЛЯЕТСЯ ДОВОЛЬНО ОПЕРАТИВНО И БЕЗ ВСЯКИХ СЛОЖНОСТЕЙ.','eng','449',NULL,NULL,NULL),(49,'2026-05-18 11:27:09',1,'2026-05-18 11:27:09',1,39,NULL,'Y','Y',500,'Английский язык для детей',304,3,4,1,'&lt;p&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp; Появление современной тенденции обучения иностранному языку с раннего возраста послужило важным стимулом для создания основательной базы эффективного обучения языку в дальнейшем. Результат не заставляет себя ждать. Уже к моменту завершения обучения на старшей ступени школьник имеет возможность владеть языком практически в совершенстве &#40;понимать иноязычную речь на слух, высказываться по определенной тематике, поддерживать разговор с собеседником&#41;. Необходимость владения английским языком неоспорима в настоящее время:<br />\n&lt;/p&gt;<br />\n&lt;ul&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;li&gt;для создания успешной карьеры в иностранных компаниях;&lt;/li&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;li&gt;для осуществления трудовой деятельности в сферах бизнеса;&lt;/li&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;li&gt;для переводческой и дипломатической карьеры;&lt;/li&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;li&gt;для совершения туристических путешествий по странам мира.&lt;/li&gt;<br />\n&lt;/ul&gt;<br />\n&lt;p&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp; При организации обучения детей английскому языку принципиально важен учет возрастных особенностей, причем как при отборе методического материала, так и при организации самого учебного процесса. Программы «Английский язык для детей» предполагают использование в процессе обучения игровых элементов, во главу угла ставятся творческие способности обучающихся, совершенно неприемлемо механическое запоминание правил.<br />\n&lt;/p&gt;<br />\n&lt;p&gt;<br />\n&nbsp;&nbsp;&nbsp;&nbsp; Самый эффективный способ обучения детей английскому языку – это игра. Именно она увлекает и захватывает детей до такой степени, что ребенок забывает, что он на уроке, что ему надо что-то выучить. В результате непроизвольного запоминания он получает знания. В связи с этим уроки английского языка, проводимые опытными, творчески работающими преподавателями школы представляют собой занимательную игру.<br />\n&lt;/p&gt;<br />\n&lt;ul&gt;<br />\n&lt;/ul&gt;','html','АНГЛИЙСКИЙ ЯЗЫК ДЛЯ ДЕТЕЙ\r\n&LT;P&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP; ПОЯВЛЕНИЕ СОВРЕМЕННОЙ ТЕНДЕНЦИИ \r\nОБУЧЕНИЯ ИНОСТРАННОМУ ЯЗЫКУ С РАННЕГО ВОЗРАСТА ПОСЛУЖИЛО ВАЖНЫМ СТИМУЛОМ ДЛЯ СОЗДАНИЯ ОСНОВАТЕЛЬНОЙ БАЗЫ ЭФФЕКТИВНОГО ОБУЧЕНИЯ ЯЗЫКУ В ДАЛЬНЕЙШЕМ. РЕЗУЛЬТАТ НЕ ЗАСТАВЛЯЕТ СЕБЯ ЖДАТЬ. УЖЕ К МОМЕНТУ ЗАВЕРШЕНИЯ ОБУЧЕНИЯ НА СТАРШЕЙ СТУПЕНИ ШКОЛЬНИК ИМЕЕТ ВОЗМОЖНОСТЬ ВЛАДЕТЬ ЯЗЫКОМ ПРАКТИЧЕСКИ В СОВЕРШЕНСТВЕ &#40;ПОНИМАТЬ ИНОЯЗЫЧНУЮ РЕЧЬ НА СЛУХ, ВЫСКАЗЫВАТЬСЯ ПО ОПРЕДЕЛЕННОЙ ТЕМАТИКЕ, ПОДДЕРЖИВАТЬ РАЗГОВОР С СОБЕСЕДНИКОМ&#41;. НЕОБХОДИМОСТЬ ВЛАДЕНИЯ АНГЛИЙСКИМ ЯЗЫКОМ НЕОСПОРИМА В НАСТОЯЩЕЕ ВРЕМЯ:\r\n&LT;/P&GT;\r\n&LT;UL&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP;&LT;LI&GT;ДЛЯ СОЗДАНИЯ УСПЕШНОЙ \r\nКАРЬЕРЫ В ИНОСТРАННЫХ КОМПАНИЯХ;&LT;/LI&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP;&LT;LI&GT;ДЛЯ ОСУЩЕСТВЛЕНИЯ ТРУДОВОЙ \r\nДЕЯТЕЛЬНОСТИ В СФЕРАХ БИЗНЕСА;&LT;/LI&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP;&LT;LI&GT;ДЛЯ ПЕРЕВОДЧЕСКОЙ И \r\nДИПЛОМАТИЧЕСКОЙ КАРЬЕРЫ;&LT;/LI&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP;&LT;LI&GT;ДЛЯ СОВЕРШЕНИЯ ТУРИСТИЧЕСКИХ \r\nПУТЕШЕСТВИЙ ПО СТРАНАМ МИРА.&LT;/LI&GT;\r\n&LT;/UL&GT;\r\n&LT;P&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP; ПРИ ОРГАНИЗАЦИИ ОБУЧЕНИЯ \r\nДЕТЕЙ АНГЛИЙСКОМУ ЯЗЫКУ ПРИНЦИПИАЛЬНО ВАЖЕН УЧЕТ ВОЗРАСТНЫХ ОСОБЕННОСТЕЙ, ПРИЧЕМ КАК ПРИ ОТБОРЕ МЕТОДИЧЕСКОГО МАТЕРИАЛА, ТАК И ПРИ ОРГАНИЗАЦИИ САМОГО УЧЕБНОГО ПРОЦЕССА. ПРОГРАММЫ «АНГЛИЙСКИЙ ЯЗЫК ДЛЯ ДЕТЕЙ» ПРЕДПОЛАГАЮТ ИСПОЛЬЗОВАНИЕ В ПРОЦЕССЕ ОБУЧЕНИЯ ИГРОВЫХ ЭЛЕМЕНТОВ, ВО ГЛАВУ УГЛА СТАВЯТСЯ ТВОРЧЕСКИЕ СПОСОБНОСТИ ОБУЧАЮЩИХСЯ, СОВЕРШЕННО НЕПРИЕМЛЕМО МЕХАНИЧЕСКОЕ ЗАПОМИНАНИЕ ПРАВИЛ.\r\n&LT;/P&GT;\r\n&LT;P&GT;\r\n&NBSP;&NBSP;&NBSP;&NBSP; САМЫЙ ЭФФЕКТИВНЫЙ СПОСОБ \r\nОБУЧЕНИЯ ДЕТЕЙ АНГЛИЙСКОМУ ЯЗЫКУ – ЭТО ИГРА. ИМЕННО ОНА УВЛЕКАЕТ И ЗАХВАТЫВАЕТ ДЕТЕЙ ДО ТАКОЙ СТЕПЕНИ, ЧТО РЕБЕНОК ЗАБЫВАЕТ, ЧТО ОН НА УРОКЕ, ЧТО ЕМУ НАДО ЧТО-ТО ВЫУЧИТЬ. В РЕЗУЛЬТАТЕ НЕПРОИЗВОЛЬНОГО ЗАПОМИНАНИЯ ОН ПОЛУЧАЕТ ЗНАНИЯ. В СВЯЗИ С ЭТИМ УРОКИ АНГЛИЙСКОГО ЯЗЫКА, ПРОВОДИМЫЕ ОПЫТНЫМИ, ТВОРЧЕСКИ РАБОТАЮЩИМИ ПРЕПОДАВАТЕЛЯМИ ШКОЛЫ ПРЕДСТАВЛЯЮТ СОБОЙ ЗАНИМАТЕЛЬНУЮ ИГРУ.\r\n&LT;/P&GT;\r\n&LT;UL&GT;\r\n&LT;/UL&GT;','engchild','450',NULL,NULL,NULL),(50,'2026-05-18 11:27:09',1,'2026-05-18 11:27:09',1,39,NULL,'Y','Y',500,'Семинары, тренинги',305,5,6,1,'<p>\n	 Формат корпоративного обучения предполагает возможность адаптировать тренинг под потребности компании-заказчика. Для этого достаточно ознакомиться с предлагаемым перечнем обучающих программ и их содержанием и внести желаемые коррективы. Наши расценки делают корпоративное обучение доступным, а качество тренингов неизменно остается высоким. Вы сможете обучить ваших сотрудников в соответствии с единым, подходящим именно вам, стандартом.\n</p>\n <b>При адаптации тренинга возможны:</b>\n<ul>\n	<li>изменение содержания тренинга в соответствии с потребностями заказчика (освещение важных для заказчика аспектов рассматриваемой темы, добавление необходимых информационных блоков);</li>\n	<li>использование в процессе обучения примеров, взятых из работы предприятия заказчика;</li>\n	<li>включение в учебную программу выступления экспертов из числа сотрудников заказчика (для демонстрации возможностей практического приложения рассматриваемого материала к реализации проектов заказчика);</li>\n	<li>обучение сотрудников в рамках внедрения заказчиком единой корпоративной системы управления проектами (КСУП);</li>\n	<li>адаптация обучающих программ под существующие в компании заказчика стандарты управления проектами.</li>\n</ul>','html','СЕМИНАРЫ, ТРЕНИНГИ\r\nФОРМАТ КОРПОРАТИВНОГО ОБУЧЕНИЯ ПРЕДПОЛАГАЕТ \r\nВОЗМОЖНОСТЬ АДАПТИРОВАТЬ ТРЕНИНГ ПОД ПОТРЕБНОСТИ КОМПАНИИ-ЗАКАЗЧИКА. ДЛЯ ЭТОГО ДОСТАТОЧНО ОЗНАКОМИТЬСЯ С ПРЕДЛАГАЕМЫМ ПЕРЕЧНЕМ ОБУЧАЮЩИХ ПРОГРАММ И ИХ СОДЕРЖАНИЕМ И ВНЕСТИ ЖЕЛАЕМЫЕ КОРРЕКТИВЫ. НАШИ РАСЦЕНКИ ДЕЛАЮТ КОРПОРАТИВНОЕ ОБУЧЕНИЕ ДОСТУПНЫМ, А КАЧЕСТВО ТРЕНИНГОВ НЕИЗМЕННО ОСТАЕТСЯ ВЫСОКИМ. ВЫ СМОЖЕТЕ ОБУЧИТЬ ВАШИХ СОТРУДНИКОВ В СООТВЕТСТВИИ С ЕДИНЫМ, ПОДХОДЯЩИМ ИМЕННО ВАМ, СТАНДАРТОМ. ПРИ АДАПТАЦИИ ТРЕНИНГА ВОЗМОЖНЫ: \r\n\r\n- ИЗМЕНЕНИЕ СОДЕРЖАНИЯ ТРЕНИНГА В СООТВЕТСТВИИ \r\nС ПОТРЕБНОСТЯМИ ЗАКАЗЧИКА (ОСВЕЩЕНИЕ ВАЖНЫХ ДЛЯ ЗАКАЗЧИКА АСПЕКТОВ РАССМАТРИВАЕМОЙ ТЕМЫ, ДОБАВЛЕНИЕ НЕОБХОДИМЫХ ИНФОРМАЦИОННЫХ БЛОКОВ); \r\n- ИСПОЛЬЗОВАНИЕ В ПРОЦЕССЕ ОБУЧЕНИЯ ПРИМЕРОВ, \r\nВЗЯТЫХ ИЗ РАБОТЫ ПРЕДПРИЯТИЯ ЗАКАЗЧИКА; \r\n- ВКЛЮЧЕНИЕ В УЧЕБНУЮ ПРОГРАММУ ВЫСТУПЛЕНИЯ \r\nЭКСПЕРТОВ ИЗ ЧИСЛА СОТРУДНИКОВ ЗАКАЗЧИКА (ДЛЯ ДЕМОНСТРАЦИИ ВОЗМОЖНОСТЕЙ ПРАКТИЧЕСКОГО ПРИЛОЖЕНИЯ РАССМАТРИВАЕМОГО МАТЕРИАЛА К РЕАЛИЗАЦИИ ПРОЕКТОВ ЗАКАЗЧИКА); \r\n- ОБУЧЕНИЕ СОТРУДНИКОВ В РАМКАХ ВНЕДРЕНИЯ \r\nЗАКАЗЧИКОМ ЕДИНОЙ КОРПОРАТИВНОЙ СИСТЕМЫ УПРАВЛЕНИЯ ПРОЕКТАМИ (КСУП); \r\n- АДАПТАЦИЯ ОБУЧАЮЩИХ ПРОГРАММ ПОД СУЩЕСТВУЮЩИЕ \r\nВ КОМПАНИИ ЗАКАЗЧИКА СТАНДАРТЫ УПРАВЛЕНИЯ ПРОЕКТАМИ.','corp','447',NULL,NULL,NULL),(51,'2026-05-18 11:27:09',1,'2026-05-18 11:27:09',1,39,NULL,'Y','Y',500,'Школа танцев',306,7,8,1,'<p>\n	 Компании давно признали действенность корпоративных мероприятий для повышения эффективности работы коллектива. Ведь подбор персонала, привлечение сотрудников (порой за огромные деньги) – это только база для формирования успешной команды. Коллектив фирмы – живой организм, и его развитие (построение команды) является наиглавнейшей задачей руководителей.\n</p>\n<p>\n	 Одно из свежих направлений в организации тим-билдинга – корпоративный танец. В отличие от агрессивных игр в пейтбол, массовых попоек в ресторане с непредсказуемым окончанием, этот тип корпоративного отдыха созидателен и подходит для сотрудников любого пола и интересов.\n</p>\n<p><strong>Плюсы корпоративного танца как формы тим-билдинга:</strong></p>\n<ol>\n	<li>Учит сотрудников коммуницировать между собой. Поставив в пару двух коллег, у которых не очень получается взаимодействовать на рабочем месте, Вы увеличиваете шансы наладить между ними эффективное общение – ведь в танце важно действовать слаженно.</li>\n	<li>Способствует сдвигу иерархии. Не секрет, что в коллективах порой складываются касты, и, к примеру, новичкам бывает трудно занять комфортное для них положение в среде сотрудников. Коллективный танец дает возможность увидеть человека с новой стороны.</li>\n	<li>Снимает стресс, связанный с конкуренцией внутри компании. В неформальной обстановке легче увидеть в коллеге человека.</li>\n	<li>Объединяет членов коллектива на эмоциональном уровне. Люди, испытывая общие позитивные эмоции, чувствуют душевное единение, помогающее противостоять хаосу рабочих процессов.</li>\n	<li>Действует терапевтически на самочувствие сотрудников, являясь формой легкого фитнеса.</li>\n</ol>\n<p>\n	 Вы можете организовать занятия корпоративным танцем, к примеру, после рабочего дня. Какой же вид танца выбрать для занятий? Конечно, выбор обусловлен предпочтениями коллектива. Для примера возьмём танго.\n</p>\n<p>\n<strong>Танго</strong> – танец страстный и энергичный. У него есть несколько уровней сложности, и люди без специальной физической подготовки смогут за месяц занятий научиться базовым движениям и начать танцевать. Множество поддержек, сильный уровень взаимодействия между партнерами заставляет действовать слаженно и синхронно. Эмоциональность танго дает выход подавляемой в условиях офисной жизни сексуальности, что необходимо для разрядки сотрудников, хотя об этом порой предпочитают лицемерно умалчивать.\n</p>\n<p>Заключая <strong>корпоративный договор с нашей школой танцев</strong>, Вы получаете:</p>\n<ul>\n	<li>Значительную скидку на абонементы</li>\n	<li>Индивидуальный подход к Вашим потребностям</li>\n	<li>Благоприятную атмосферу в коллективе</li>\n</ul>','html','ШКОЛА ТАНЦЕВ\r\nКОМПАНИИ ДАВНО ПРИЗНАЛИ ДЕЙСТВЕННОСТЬ \r\nКОРПОРАТИВНЫХ МЕРОПРИЯТИЙ ДЛЯ ПОВЫШЕНИЯ ЭФФЕКТИВНОСТИ РАБОТЫ КОЛЛЕКТИВА. ВЕДЬ ПОДБОР ПЕРСОНАЛА, ПРИВЛЕЧЕНИЕ СОТРУДНИКОВ (ПОРОЙ ЗА ОГРОМНЫЕ ДЕНЬГИ) – ЭТО ТОЛЬКО БАЗА ДЛЯ ФОРМИРОВАНИЯ УСПЕШНОЙ КОМАНДЫ. КОЛЛЕКТИВ ФИРМЫ – ЖИВОЙ ОРГАНИЗМ, И ЕГО РАЗВИТИЕ (ПОСТРОЕНИЕ КОМАНДЫ) ЯВЛЯЕТСЯ НАИГЛАВНЕЙШЕЙ ЗАДАЧЕЙ РУКОВОДИТЕЛЕЙ. \r\n\r\nОДНО ИЗ СВЕЖИХ НАПРАВЛЕНИЙ В ОРГАНИЗАЦИИ \r\nТИМ-БИЛДИНГА – КОРПОРАТИВНЫЙ ТАНЕЦ. В ОТЛИЧИЕ ОТ АГРЕССИВНЫХ ИГР В ПЕЙТБОЛ, МАССОВЫХ ПОПОЕК В РЕСТОРАНЕ С НЕПРЕДСКАЗУЕМЫМ ОКОНЧАНИЕМ, ЭТОТ ТИП КОРПОРАТИВНОГО ОТДЫХА СОЗИДАТЕЛЕН И ПОДХОДИТ ДЛЯ СОТРУДНИКОВ ЛЮБОГО ПОЛА И ИНТЕРЕСОВ. \r\n\r\nПЛЮСЫ КОРПОРАТИВНОГО ТАНЦА КАК ФОРМЫ ТИМ-БИЛДИНГА: \r\n- УЧИТ СОТРУДНИКОВ КОММУНИЦИРОВАТЬ МЕЖДУ \r\nСОБОЙ. ПОСТАВИВ В ПАРУ ДВУХ КОЛЛЕГ, У КОТОРЫХ НЕ ОЧЕНЬ ПОЛУЧАЕТСЯ ВЗАИМОДЕЙСТВОВАТЬ НА РАБОЧЕМ МЕСТЕ, ВЫ УВЕЛИЧИВАЕТЕ ШАНСЫ НАЛАДИТЬ МЕЖДУ НИМИ ЭФФЕКТИВНОЕ ОБЩЕНИЕ – ВЕДЬ В ТАНЦЕ ВАЖНО ДЕЙСТВОВАТЬ СЛАЖЕННО. \r\n- СПОСОБСТВУЕТ СДВИГУ ИЕРАРХИИ. НЕ СЕКРЕТ, \r\nЧТО В КОЛЛЕКТИВАХ ПОРОЙ СКЛАДЫВАЮТСЯ КАСТЫ, И, К ПРИМЕРУ, НОВИЧКАМ БЫВАЕТ ТРУДНО ЗАНЯТЬ КОМФОРТНОЕ ДЛЯ НИХ ПОЛОЖЕНИЕ В СРЕДЕ СОТРУДНИКОВ. КОЛЛЕКТИВНЫЙ ТАНЕЦ ДАЕТ ВОЗМОЖНОСТЬ УВИДЕТЬ ЧЕЛОВЕКА С НОВОЙ СТОРОНЫ. \r\n- СНИМАЕТ СТРЕСС, СВЯЗАННЫЙ С КОНКУРЕНЦИЕЙ \r\nВНУТРИ КОМПАНИИ. В НЕФОРМАЛЬНОЙ ОБСТАНОВКЕ ЛЕГЧЕ УВИДЕТЬ В КОЛЛЕГЕ ЧЕЛОВЕКА. \r\n- ОБЪЕДИНЯЕТ ЧЛЕНОВ КОЛЛЕКТИВА НА ЭМОЦИОНАЛЬНОМ \r\nУРОВНЕ. ЛЮДИ, ИСПЫТЫВАЯ ОБЩИЕ ПОЗИТИВНЫЕ ЭМОЦИИ, ЧУВСТВУЮТ ДУШЕВНОЕ ЕДИНЕНИЕ, ПОМОГАЮЩЕЕ ПРОТИВОСТОЯТЬ ХАОСУ РАБОЧИХ ПРОЦЕССОВ. \r\n- ДЕЙСТВУЕТ ТЕРАПЕВТИЧЕСКИ НА САМОЧУВСТВИЕ \r\nСОТРУДНИКОВ, ЯВЛЯЯСЬ ФОРМОЙ ЛЕГКОГО ФИТНЕСА. \r\n\r\nВЫ МОЖЕТЕ ОРГАНИЗОВАТЬ ЗАНЯТИЯ КОРПОРАТИВНЫМ \r\nТАНЦЕМ, К ПРИМЕРУ, ПОСЛЕ РАБОЧЕГО ДНЯ. КАКОЙ ЖЕ ВИД ТАНЦА ВЫБРАТЬ ДЛЯ ЗАНЯТИЙ? КОНЕЧНО, ВЫБОР ОБУСЛОВЛЕН ПРЕДПОЧТЕНИЯМИ КОЛЛЕКТИВА. ДЛЯ ПРИМЕРА ВОЗЬМЁМ ТАНГО. \r\n\r\nТАНГО – ТАНЕЦ СТРАСТНЫЙ И ЭНЕРГИЧНЫЙ. У \r\nНЕГО ЕСТЬ НЕСКОЛЬКО УРОВНЕЙ СЛОЖНОСТИ, И ЛЮДИ БЕЗ СПЕЦИАЛЬНОЙ ФИЗИЧЕСКОЙ ПОДГОТОВКИ СМОГУТ ЗА МЕСЯЦ ЗАНЯТИЙ НАУЧИТЬСЯ БАЗОВЫМ ДВИЖЕНИЯМ И НАЧАТЬ ТАНЦЕВАТЬ. МНОЖЕСТВО ПОДДЕРЖЕК, СИЛЬНЫЙ УРОВЕНЬ ВЗАИМОДЕЙСТВИЯ МЕЖДУ ПАРТНЕРАМИ ЗАСТАВЛЯЕТ ДЕЙСТВОВАТЬ СЛАЖЕННО И СИНХРОННО. ЭМОЦИОНАЛЬНОСТЬ ТАНГО ДАЕТ ВЫХОД ПОДАВЛЯЕМОЙ В УСЛОВИЯХ ОФИСНОЙ ЖИЗНИ СЕКСУАЛЬНОСТИ, ЧТО НЕОБХОДИМО ДЛЯ РАЗРЯДКИ СОТРУДНИКОВ, ХОТЯ ОБ ЭТОМ ПОРОЙ ПРЕДПОЧИТАЮТ ЛИЦЕМЕРНО УМАЛЧИВАТЬ. \r\n\r\nЗАКЛЮЧАЯ КОРПОРАТИВНЫЙ ДОГОВОР С НАШЕЙ \r\nШКОЛОЙ ТАНЦЕВ, ВЫ ПОЛУЧАЕТЕ: \r\n\r\n- ЗНАЧИТЕЛЬНУЮ СКИДКУ НА АБОНЕМЕНТЫ \r\n- ИНДИВИДУАЛЬНЫЙ ПОДХОД К ВАШИМ ПОТРЕБНОСТЯМ \r\n- БЛАГОПРИЯТНУЮ АТМОСФЕРУ В КОЛЛЕКТИВЕ','scholldance','448',NULL,NULL,NULL),(52,'2026-06-05 12:10:50',1,'2026-05-18 11:27:10',1,40,NULL,'N','N',500,'Автоматизация',342,1,2,1,'<h2>Автоматизация бизнеса</h2>\n <br>\n Автоматизация торговли – это процесс внедрения в организацию специального оборудования или программного обеспечения. Направленная автоматизация оптимизирует бизнес-процессы, увеличивает эффективность продаж и не допускает возникновения ошибок из-за человеческого фактора.<br>\n <br>\n Компания «Олл Корп» уже автоматизировала 126 предприятий. Мы помогаем добиться финансового успеха и доверия ваших клиентов с помощью современных методов оптимизации. Автоматизация бизнеса поможет структурировать работу и принимать только правильные и эффективные для компании решения.<br>\n <br>','html','АВТОМАТИЗАЦИЯ\r\nАВТОМАТИЗАЦИЯ БИЗНЕСА \r\nАВТОМАТИЗАЦИЯ ТОРГОВЛИ – ЭТО ПРОЦЕСС ВНЕДРЕНИЯ \r\nВ ОРГАНИЗАЦИЮ СПЕЦИАЛЬНОГО ОБОРУДОВАНИЯ ИЛИ ПРОГРАММНОГО ОБЕСПЕЧЕНИЯ. НАПРАВЛЕННАЯ АВТОМАТИЗАЦИЯ ОПТИМИЗИРУЕТ БИЗНЕС-ПРОЦЕССЫ, УВЕЛИЧИВАЕТ ЭФФЕКТИВНОСТЬ ПРОДАЖ И НЕ ДОПУСКАЕТ ВОЗНИКНОВЕНИЯ ОШИБОК ИЗ-ЗА ЧЕЛОВЕЧЕСКОГО ФАКТОРА.\r\n\r\nКОМПАНИЯ «ОЛЛ КОРП» УЖЕ АВТОМАТИЗИРОВАЛА \r\n126 ПРЕДПРИЯТИЙ. МЫ ПОМОГАЕМ ДОБИТЬСЯ ФИНАНСОВОГО УСПЕХА И ДОВЕРИЯ ВАШИХ КЛИЕНТОВ С ПОМОЩЬЮ СОВРЕМЕННЫХ МЕТОДОВ ОПТИМИЗАЦИИ. АВТОМАТИЗАЦИЯ БИЗНЕСА ПОМОЖЕТ СТРУКТУРИРОВАТЬ РАБОТУ И ПРИНИМАТЬ ТОЛЬКО ПРАВИЛЬНЫЕ И ЭФФЕКТИВНЫЕ ДЛЯ КОМПАНИИ РЕШЕНИЯ.','avtomatizatsiya','430',NULL,NULL,NULL),(53,'2026-06-05 12:10:50',1,'2026-05-18 11:27:10',1,40,NULL,'N','N',500,'Аренда спецтехники',343,3,4,1,'<h2>Аренда строительной и дорожной техники на любой срок<br>\n </h2>\n Мы предлагаем аренду любых видов спецтехники для строительных, погрузочно-разгрузочных и уборочных работ. Компания «Олл Корп» гарантирует подачу техники в любую точку Москвы и Московской области в нужный срок. Вы можете заказать спецтехнику в выходные и праздничные дни, а также в ночное время суток. Для консультации по услуге и подбору техники свяжитесь с нашим менеджером. При заказе 2х и более единиц спецтехники вы получите скидку 10% на все работы. <br>\n <br>\n<h3>Дополнительные работы</h3>\n Наши сотрудники подготовлены ко всем видам строительных работ, поэтому при необходимости вы можете заказать любые услуги, связанные со спецтехникой: <br>\n <br>\n<ul>\n	<li>дорожные работы</li>\n	<li>\n	транспортировку грузов</li>\n	<li>\n	возведение конструкций</li>\n	<li>\n	и другое.</li>\n</ul>','html','АРЕНДА СПЕЦТЕХНИКИ\r\nАРЕНДА СТРОИТЕЛЬНОЙ И ДОРОЖНОЙ ТЕХНИКИ \r\nНА ЛЮБОЙ СРОК\r\n МЫ ПРЕДЛАГАЕМ АРЕНДУ ЛЮБЫХ ВИДОВ СПЕЦТЕХНИКИ \r\nДЛЯ СТРОИТЕЛЬНЫХ, ПОГРУЗОЧНО-РАЗГРУЗОЧНЫХ И УБОРОЧНЫХ РАБОТ. КОМПАНИЯ «ОЛЛ КОРП» ГАРАНТИРУЕТ ПОДАЧУ ТЕХНИКИ В ЛЮБУЮ ТОЧКУ МОСКВЫ И МОСКОВСКОЙ ОБЛАСТИ В НУЖНЫЙ СРОК. ВЫ МОЖЕТЕ ЗАКАЗАТЬ СПЕЦТЕХНИКУ В ВЫХОДНЫЕ И ПРАЗДНИЧНЫЕ ДНИ, А ТАКЖЕ В НОЧНОЕ ВРЕМЯ СУТОК. ДЛЯ КОНСУЛЬТАЦИИ ПО УСЛУГЕ И ПОДБОРУ ТЕХНИКИ СВЯЖИТЕСЬ С НАШИМ МЕНЕДЖЕРОМ. ПРИ ЗАКАЗЕ 2Х И БОЛЕЕ ЕДИНИЦ СПЕЦТЕХНИКИ ВЫ ПОЛУЧИТЕ СКИДКУ 10% НА ВСЕ РАБОТЫ. \r\n\r\nДОПОЛНИТЕЛЬНЫЕ РАБОТЫ НАШИ СОТРУДНИКИ \r\nПОДГОТОВЛЕНЫ КО ВСЕМ ВИДАМ СТРОИТЕЛЬНЫХ РАБОТ, ПОЭТОМУ ПРИ НЕОБХОДИМОСТИ ВЫ МОЖЕТЕ ЗАКАЗАТЬ ЛЮБЫЕ УСЛУГИ, СВЯЗАННЫЕ СО СПЕЦТЕХНИКОЙ: \r\n\r\n\r\n\r\n- ДОРОЖНЫЕ РАБОТЫ \r\n- ТРАНСПОРТИРОВКУ ГРУЗОВ \r\n- ВОЗВЕДЕНИЕ КОНСТРУКЦИЙ \r\n- И ДРУГОЕ.','arenda-spetstekhniki','470',NULL,NULL,NULL),(54,'2026-06-05 12:10:50',1,'2026-05-18 11:27:10',1,40,NULL,'N','N',500,'Инженерные системы',344,7,8,1,'<h2>Проектирование и монтаж инженерных систем</h2>\n Компания «Олл Корп» успешно воплощает в жизнь проекты в сфере инженерных систем любых сложностей и масштабов. Наши клиенты получают высокий уровень качества за счет грамотного подхода к проектированию и монтажу инженерных систем. На каждом этапе проекта специалисты компании осуществляют техническую поддержку и помогают с оформлением документации.&nbsp; <br>\n <br>\n<h3>\nПочему нас рекомендуют? </h3>\n<p>\n</p>\n<ul>\n	<li>Делаем качественно. Только проверенные производители и поставщики, чтобы продлить срок службы системы. </li>\n	<li>Говорим честно. Мы документируем все договоренности и соблюдаем их. Честно работаем с надзорными органами. </li>\n	<li>Работаем профессионально. Планируем финансовую и техническую составляющие проекта до самых мелочей. Контролируем процесс с даты создания до сдачи проекта. </li>\n</ul>\n<p>\n</p>\n<p>\n	 После завершения проекта мы не забываем о нем, а продолжаем сервисное обслуживание и контролируем его состояние. Так вы будете уверены в долговечности системы и сможете проконсультироваться с нашими сотрудниками в любое время. Также у нашей компании есть склад запчастей для любой инженерной системы, поэтому при необходимости мы быстро устраним неполадку или модернизируем ваш проект.<br>\n</p>','html','ИНЖЕНЕРНЫЕ СИСТЕМЫ\r\nПРОЕКТИРОВАНИЕ И МОНТАЖ ИНЖЕНЕРНЫХ СИСТЕМ \r\nКОМПАНИЯ «ОЛЛ КОРП» УСПЕШНО ВОПЛОЩАЕТ В ЖИЗНЬ ПРОЕКТЫ В СФЕРЕ ИНЖЕНЕРНЫХ СИСТЕМ ЛЮБЫХ СЛОЖНОСТЕЙ И МАСШТАБОВ. НАШИ КЛИЕНТЫ ПОЛУЧАЮТ ВЫСОКИЙ УРОВЕНЬ КАЧЕСТВА ЗА СЧЕТ ГРАМОТНОГО ПОДХОДА К ПРОЕКТИРОВАНИЮ И МОНТАЖУ ИНЖЕНЕРНЫХ СИСТЕМ. НА КАЖДОМ ЭТАПЕ ПРОЕКТА СПЕЦИАЛИСТЫ КОМПАНИИ ОСУЩЕСТВЛЯЮТ ТЕХНИЧЕСКУЮ ПОДДЕРЖКУ И ПОМОГАЮТ С ОФОРМЛЕНИЕМ ДОКУМЕНТАЦИИ.&NBSP; \r\n\r\n ПОЧЕМУ НАС РЕКОМЕНДУЮТ? \r\n\r\n \r\n\r\n- ДЕЛАЕМ КАЧЕСТВЕННО. ТОЛЬКО ПРОВЕРЕННЫЕ \r\nПРОИЗВОДИТЕЛИ И ПОСТАВЩИКИ, ЧТОБЫ ПРОДЛИТЬ СРОК СЛУЖБЫ СИСТЕМЫ. \r\n- ГОВОРИМ ЧЕСТНО. МЫ ДОКУМЕНТИРУЕМ ВСЕ ДОГОВОРЕННОСТИ \r\nИ СОБЛЮДАЕМ ИХ. ЧЕСТНО РАБОТАЕМ С НАДЗОРНЫМИ ОРГАНАМИ. \r\n- РАБОТАЕМ ПРОФЕССИОНАЛЬНО. ПЛАНИРУЕМ ФИНАНСОВУЮ \r\nИ ТЕХНИЧЕСКУЮ СОСТАВЛЯЮЩИЕ ПРОЕКТА ДО САМЫХ МЕЛОЧЕЙ. КОНТРОЛИРУЕМ ПРОЦЕСС С ДАТЫ СОЗДАНИЯ ДО СДАЧИ ПРОЕКТА. \r\n\r\n \r\n\r\nПОСЛЕ ЗАВЕРШЕНИЯ ПРОЕКТА МЫ НЕ ЗАБЫВАЕМ \r\nО НЕМ, А ПРОДОЛЖАЕМ СЕРВИСНОЕ ОБСЛУЖИВАНИЕ И КОНТРОЛИРУЕМ ЕГО СОСТОЯНИЕ. ТАК ВЫ БУДЕТЕ УВЕРЕНЫ В ДОЛГОВЕЧНОСТИ СИСТЕМЫ И СМОЖЕТЕ ПРОКОНСУЛЬТИРОВАТЬСЯ С НАШИМИ СОТРУДНИКАМИ В ЛЮБОЕ ВРЕМЯ. ТАКЖЕ У НАШЕЙ КОМПАНИИ ЕСТЬ СКЛАД ЗАПЧАСТЕЙ ДЛЯ ЛЮБОЙ ИНЖЕНЕРНОЙ СИСТЕМЫ, ПОЭТОМУ ПРИ НЕОБХОДИМОСТИ МЫ БЫСТРО УСТРАНИМ НЕПОЛАДКУ ИЛИ МОДЕРНИЗИРУЕМ ВАШ ПРОЕКТ.','inzhenernye-sistemy','428',NULL,NULL,NULL),(55,'2026-06-05 12:05:34',1,'2026-05-18 11:27:10',1,40,NULL,'N','N',500,'Металлоконструкции',345,11,12,1,'<h2>Монтаж и обработка металлоконструкций</h2>\n <span style=\"color: #000000;\">Компания «Олл Корп» производит металлоконструкции на заказ по индивидуальным проектам с 2008 года. Из-за прочности и долговечности металлоконструкции получили широкое распространение в строительстве. От качества их исполнения зависит срок службы и удобство эксплуатации строения. Среди прочих преимуществ металлоконструкций – устойчивость к тяжелым климатическим условиям, удобство возведения на сложном рельефе и скорость установки. Назначение зданий, основой которых являются металлоконструкции, значения не имеет. </span> <br>\n <br>\n <span style=\"color: #000000;\">Компания «Олл Корп» выполнит заказ любой сложности и объема по конкурентным ценам. Собственное конструкторское бюро разработает чертеж специально для вас. При необходимости мы можем его модифицировать или выполнить проект по чертежам заказчика.</span><br>\n <br>','html','МЕТАЛЛОКОНСТРУКЦИИ\r\nМОНТАЖ И ОБРАБОТКА МЕТАЛЛОКОНСТРУКЦИЙ \r\nКОМПАНИЯ «ОЛЛ КОРП» ПРОИЗВОДИТ МЕТАЛЛОКОНСТРУКЦИИ НА ЗАКАЗ ПО ИНДИВИДУАЛЬНЫМ ПРОЕКТАМ С 2008 ГОДА. ИЗ-ЗА ПРОЧНОСТИ И ДОЛГОВЕЧНОСТИ МЕТАЛЛОКОНСТРУКЦИИ ПОЛУЧИЛИ ШИРОКОЕ РАСПРОСТРАНЕНИЕ В СТРОИТЕЛЬСТВЕ. ОТ КАЧЕСТВА ИХ ИСПОЛНЕНИЯ ЗАВИСИТ СРОК СЛУЖБЫ И УДОБСТВО ЭКСПЛУАТАЦИИ СТРОЕНИЯ. СРЕДИ ПРОЧИХ ПРЕИМУЩЕСТВ МЕТАЛЛОКОНСТРУКЦИЙ – УСТОЙЧИВОСТЬ К ТЯЖЕЛЫМ КЛИМАТИЧЕСКИМ УСЛОВИЯМ, УДОБСТВО ВОЗВЕДЕНИЯ НА СЛОЖНОМ РЕЛЬЕФЕ И СКОРОСТЬ УСТАНОВКИ. НАЗНАЧЕНИЕ ЗДАНИЙ, ОСНОВОЙ КОТОРЫХ ЯВЛЯЮТСЯ МЕТАЛЛОКОНСТРУКЦИИ, ЗНАЧЕНИЯ НЕ ИМЕЕТ. \r\n\r\nКОМПАНИЯ «ОЛЛ КОРП» ВЫПОЛНИТ ЗАКАЗ ЛЮБОЙ \r\nСЛОЖНОСТИ И ОБЪЕМА ПО КОНКУРЕНТНЫМ ЦЕНАМ. СОБСТВЕННОЕ КОНСТРУКТОРСКОЕ БЮРО РАЗРАБОТАЕТ ЧЕРТЕЖ СПЕЦИАЛЬНО ДЛЯ ВАС. ПРИ НЕОБХОДИМОСТИ МЫ МОЖЕМ ЕГО МОДИФИЦИРОВАТЬ ИЛИ ВЫПОЛНИТЬ ПРОЕКТ ПО ЧЕРТЕЖАМ ЗАКАЗЧИКА.','metallokonstruktsii','429',NULL,NULL,NULL),(56,'2026-06-05 12:05:15',1,'2026-05-18 11:27:10',1,40,NULL,'N','N',500,'Отделка фасада',346,13,14,1,'<h2>Отделка фасадов в Москве и МО</h2>\n<p class=\"introtext\">\n	 Отделка фасадов зданий улучшает внешний вид здания, повышает теплоизоляцию сооружения и снижает уровень шума. Если вы недавно закончили строительство дома, то позаботьтесь и о наружной отделке, чтобы защитить строение от внешних воздействий.\n</p>\n Специалисты компании «Олл Корп» имеют девятилетний опыт в отделочных работах и современные инструменты для любых материалов. Мы предлагаем вам индивидуальный подход к проекту, где вы совместно с нашими дизайнерами подберет приятный облик для вашего дома.<br>\n<h4>У нас можно заказать отделку из любых материалов:</h4>\n<ul>\n	<li>натуральный и искусственный камень</li>\n	<li>\n	деревянные или металлические панели</li>\n	<li>\n	декоративная плитка или штукатурка</li>\n	<li>\n	клинкерный отделочный кирпич&nbsp;</li>\n	<li>\n	сайдинг</li>\n	<li>\n	фасадные кассеты.</li>\n	<li>\n	и другие</li>\n</ul>\n <br>\n Выполняя отделку фасада, очень важно выбрать качественные материалы, которые не только сохранят свои эстетические свойства, но и выдержать любые погодные условия без последствий.Также вы можете использовать комбинации из отделочных материалов, но учтите, что каждый материал обладает своими характеристиками.<br>\n <br>\n <span style=\"color: #222222; font-size: 1.33em; font-weight: bold;\">Расход материалов при отделке фасада<br>\n </span><br>\n<table class=\"table table-bordered\">\n<thead>\n<tr>\n	<th>\n		 Наименование материала\n	</th>\n	<th>\n		 Единица измерения\n	</th>\n	<th>\n		 Расход на 1 кв. м.\n	</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n	<td>\n		 Армировочно-клеевая смесь (для приклеивания плит)\n	</td>\n	<td>\n		 кг\n	</td>\n	<td>\n		 5, 10\n	</td>\n</tr>\n<tr>\n	<td>\n		 Дюбель (для крепления утеплителя)\n	</td>\n	<td>\n		 шт.\n	</td>\n	<td>\n		 12\n	</td>\n</tr>\n<tr>\n	<td>\n		 Армирующая сетка из стекловолокна\n	</td>\n	<td>\n		 кв.м.\n	</td>\n	<td>\n		 1, 15\n	</td>\n</tr>\n<tr>\n	<td>\n		 Декоративная плитка\n	</td>\n	<td>\n		 шт.\n	</td>\n	<td>\n		 3\n	</td>\n</tr>\n</tbody>\n</table>\n <br>\n Компания «Олл Корп» подберет для вас оптимальный вариант исходя из ваших финансовых возможностей и личных предпочтений. Срок работ составляет от 1 до 10 рабочих дней в зависимости от сложности и объема работ. Вы уже сейчас можете рассказать нам о своих пожеланиях и отправить заявку – наш менеджер свяжется с вами в ближайшее время.<br>\n <br>','html','ОТДЕЛКА ФАСАДА\r\nОТДЕЛКА ФАСАДОВ В МОСКВЕ И МО \r\n\r\nОТДЕЛКА ФАСАДОВ ЗДАНИЙ УЛУЧШАЕТ ВНЕШНИЙ \r\nВИД ЗДАНИЯ, ПОВЫШАЕТ ТЕПЛОИЗОЛЯЦИЮ СООРУЖЕНИЯ И СНИЖАЕТ УРОВЕНЬ ШУМА. ЕСЛИ ВЫ НЕДАВНО ЗАКОНЧИЛИ СТРОИТЕЛЬСТВО ДОМА, ТО ПОЗАБОТЬТЕСЬ И О НАРУЖНОЙ ОТДЕЛКЕ, ЧТОБЫ ЗАЩИТИТЬ СТРОЕНИЕ ОТ ВНЕШНИХ ВОЗДЕЙСТВИЙ. СПЕЦИАЛИСТЫ КОМПАНИИ «ОЛЛ КОРП» ИМЕЮТ ДЕВЯТИЛЕТНИЙ ОПЫТ В ОТДЕЛОЧНЫХ РАБОТАХ И СОВРЕМЕННЫЕ ИНСТРУМЕНТЫ ДЛЯ ЛЮБЫХ МАТЕРИАЛОВ. МЫ ПРЕДЛАГАЕМ ВАМ ИНДИВИДУАЛЬНЫЙ ПОДХОД К ПРОЕКТУ, ГДЕ ВЫ СОВМЕСТНО С НАШИМИ ДИЗАЙНЕРАМИ ПОДБЕРЕТ ПРИЯТНЫЙ ОБЛИК ДЛЯ ВАШЕГО ДОМА.\r\nУ НАС МОЖНО ЗАКАЗАТЬ ОТДЕЛКУ ИЗ ЛЮБЫХ МАТЕРИАЛОВ: \r\n\r\n- НАТУРАЛЬНЫЙ И ИСКУССТВЕННЫЙ КАМЕНЬ \r\n- ДЕРЕВЯННЫЕ ИЛИ МЕТАЛЛИЧЕСКИЕ ПАНЕЛИ \r\n- ДЕКОРАТИВНАЯ ПЛИТКА ИЛИ ШТУКАТУРКА \r\n- КЛИНКЕРНЫЙ ОТДЕЛОЧНЫЙ КИРПИЧ&NBSP; \r\n- САЙДИНГ \r\n- ФАСАДНЫЕ КАССЕТЫ. \r\n- И ДРУГИЕ \r\nВЫПОЛНЯЯ ОТДЕЛКУ ФАСАДА, ОЧЕНЬ ВАЖНО ВЫБРАТЬ \r\nКАЧЕСТВЕННЫЕ МАТЕРИАЛЫ, КОТОРЫЕ НЕ ТОЛЬКО СОХРАНЯТ СВОИ ЭСТЕТИЧЕСКИЕ СВОЙСТВА, НО И ВЫДЕРЖАТЬ ЛЮБЫЕ ПОГОДНЫЕ УСЛОВИЯ БЕЗ ПОСЛЕДСТВИЙ.ТАКЖЕ ВЫ МОЖЕТЕ ИСПОЛЬЗОВАТЬ КОМБИНАЦИИ ИЗ ОТДЕЛОЧНЫХ МАТЕРИАЛОВ, НО УЧТИТЕ, ЧТО КАЖДЫЙ МАТЕРИАЛ ОБЛАДАЕТ СВОИМИ ХАРАКТЕРИСТИКАМИ.\r\n\r\nРАСХОД МАТЕРИАЛОВ ПРИ ОТДЕЛКЕ ФАСАДА\r\n\r\n\r\n НАИМЕНОВАНИЕ МАТЕРИАЛА      ЕДИНИЦА ИЗМЕРЕНИЯ \r\n     РАСХОД НА 1 КВ. М.      \r\n АРМИРОВОЧНО-КЛЕЕВАЯ СМЕСЬ (ДЛЯ ПРИКЛЕИВАНИЯ \r\nПЛИТ)      КГ      5, 10      \r\n ДЮБЕЛЬ (ДЛЯ КРЕПЛЕНИЯ УТЕПЛИТЕЛЯ)      ШТ. \r\n     12      \r\n АРМИРУЮЩАЯ СЕТКА ИЗ СТЕКЛОВОЛОКНА      КВ.М. \r\n     1, 15      \r\n ДЕКОРАТИВНАЯ ПЛИТКА      ШТ.      3      \r\n \r\nКОМПАНИЯ «ОЛЛ КОРП» ПОДБЕРЕТ ДЛЯ ВАС ОПТИМАЛЬНЫЙ \r\nВАРИАНТ ИСХОДЯ ИЗ ВАШИХ ФИНАНСОВЫХ ВОЗМОЖНОСТЕЙ И ЛИЧНЫХ ПРЕДПОЧТЕНИЙ. СРОК РАБОТ СОСТАВЛЯЕТ ОТ 1 ДО 10 РАБОЧИХ ДНЕЙ В ЗАВИСИМОСТИ ОТ СЛОЖНОСТИ И ОБЪЕМА РАБОТ. ВЫ УЖЕ СЕЙЧАС МОЖЕТЕ РАССКАЗАТЬ НАМ О СВОИХ ПОЖЕЛАНИЯХ И ОТПРАВИТЬ ЗАЯВКУ – НАШ МЕНЕДЖЕР СВЯЖЕТСЯ С ВАМИ В БЛИЖАЙШЕЕ ВРЕМЯ.','otdelka-fasada','431',NULL,NULL,NULL),(57,'2026-06-05 12:05:15',1,'2026-05-18 11:27:10',1,40,NULL,'N','N',500,'Проектирование',347,15,16,1,'<h2>Проектирование систем в Москве и МО</h2>\n<p class=\"introtext\">\n	 Проектирование – основа положительного результата. Получившийся проект становится целостной структурой моделей, свойств или характеристик одной системы. При проектировании ставятся цели и задачи проекта, оцениваются риски и принимаются во внимание ограничения. Наша компания занимается проектированием с 2008 года. Предлагаем услуги по проектированию дизайнов интерьеров, инженерных сетей и электротехнического направления.\n</p>\n<h3> <span style=\"color: #000000;\">Проектная деятельность включает в себя:&nbsp;</span></h3>\n<ul>\n	<li style=\"color: #000000;\">разработку проекта</li>\n	<li style=\"color: #000000;\">обоснование, согласование, оценку проекта</li>\n	<li style=\"color: #000000;\">реализацию проекта</li>\n</ul>\n <br>','html','ПРОЕКТИРОВАНИЕ\r\nПРОЕКТИРОВАНИЕ СИСТЕМ В МОСКВЕ И МО \r\n\r\nПРОЕКТИРОВАНИЕ – ОСНОВА ПОЛОЖИТЕЛЬНОГО \r\nРЕЗУЛЬТАТА. ПОЛУЧИВШИЙСЯ ПРОЕКТ СТАНОВИТСЯ ЦЕЛОСТНОЙ СТРУКТУРОЙ МОДЕЛЕЙ, СВОЙСТВ ИЛИ ХАРАКТЕРИСТИК ОДНОЙ СИСТЕМЫ. ПРИ ПРОЕКТИРОВАНИИ СТАВЯТСЯ ЦЕЛИ И ЗАДАЧИ ПРОЕКТА, ОЦЕНИВАЮТСЯ РИСКИ И ПРИНИМАЮТСЯ ВО ВНИМАНИЕ ОГРАНИЧЕНИЯ. НАША КОМПАНИЯ ЗАНИМАЕТСЯ ПРОЕКТИРОВАНИЕМ С 2008 ГОДА. ПРЕДЛАГАЕМ УСЛУГИ ПО ПРОЕКТИРОВАНИЮ ДИЗАЙНОВ ИНТЕРЬЕРОВ, ИНЖЕНЕРНЫХ СЕТЕЙ И ЭЛЕКТРОТЕХНИЧЕСКОГО НАПРАВЛЕНИЯ. ПРОЕКТНАЯ ДЕЯТЕЛЬНОСТЬ ВКЛЮЧАЕТ В СЕБЯ:&NBSP; \r\n\r\n- РАЗРАБОТКУ ПРОЕКТА \r\n- ОБОСНОВАНИЕ, СОГЛАСОВАНИЕ, ОЦЕНКУ ПРОЕКТА \r\n- РЕАЛИЗАЦИЮ ПРОЕКТА','proektirovanie','427',NULL,NULL,NULL),(58,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Аренда спецтехники',398,1,10,1,'Компания «Олл Корп» сдает в аренду спецтехнику для разных строительных мероприятий. Приобретение спецтехники обходится предприятиям очень дорого, а в итоге машины работают не чаще 1-2 раз в год. Аренда – это рациональное решение в сфере строительства. <br>\n <br>\nВ каталоге вы найдете подробные описания оборудования и стоимость аренды за одну смену. Весь товарный ряд приобретен после 2015 года, поэтому вы можете быть уверены в исправности машин и качестве их работы. В сезон строительных работ (апрель-октябрь) просим делать заказ минимум за 7 дней до начала работ.','html','АРЕНДА СПЕЦТЕХНИКИ\r\nКОМПАНИЯ «ОЛЛ КОРП» СДАЕТ В АРЕНДУ СПЕЦТЕХНИКУ \r\nДЛЯ РАЗНЫХ СТРОИТЕЛЬНЫХ МЕРОПРИЯТИЙ. ПРИОБРЕТЕНИЕ СПЕЦТЕХНИКИ ОБХОДИТСЯ ПРЕДПРИЯТИЯМ ОЧЕНЬ ДОРОГО, А В ИТОГЕ МАШИНЫ РАБОТАЮТ НЕ ЧАЩЕ 1-2 РАЗ В ГОД. АРЕНДА – ЭТО РАЦИОНАЛЬНОЕ РЕШЕНИЕ В СФЕРЕ СТРОИТЕЛЬСТВА. \r\n\r\nВ КАТАЛОГЕ ВЫ НАЙДЕТЕ ПОДРОБНЫЕ ОПИСАНИЯ \r\nОБОРУДОВАНИЯ И СТОИМОСТЬ АРЕНДЫ ЗА ОДНУ СМЕНУ. ВЕСЬ ТОВАРНЫЙ РЯД ПРИОБРЕТЕН ПОСЛЕ 2015 ГОДА, ПОЭТОМУ ВЫ МОЖЕТЕ БЫТЬ УВЕРЕНЫ В ИСПРАВНОСТИ МАШИН И КАЧЕСТВЕ ИХ РАБОТЫ. В СЕЗОН СТРОИТЕЛЬНЫХ РАБОТ (АПРЕЛЬ-ОКТЯБРЬ) ПРОСИМ ДЕЛАТЬ ЗАКАЗ МИНИМУМ ЗА 7 ДНЕЙ ДО НАЧАЛА РАБОТ.','arenda-tekhniki','411',NULL,NULL,NULL),(59,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,58,'Y','N',500,'Автокраны',399,2,3,2,'Автокраны производителей XCMG и Liebherr грузоподъемностью от 14 тонн сдаются в аренду на 2 и более смен. Возможна длительная круглосуточная аренда. Экономичные модели для любых видов строительных работ. Краны легко ездят по бездорожью и просты в эксплуатации. В нашем автопарке есть автокраны с разным количеством рабочих скоростей и длиной вылета рабочей стрелы. <br>\n <br>\nМашины оборудованы необходимыми и современными средствами контроля и безопасности. По требованию спецтехника сдается в аренду с водителем-оператором и топливом, возможны услуги без солярки по более низкой цене. Стоимость аренды будет снижена при заказе спецтехники на 20 суток и более. Обратитесь к менеджеру для оперативного оформления заказа.','html','АВТОКРАНЫ\r\nАВТОКРАНЫ ПРОИЗВОДИТЕЛЕЙ XCMG И LIEBHERR ГРУЗОПОДЪЕМНОСТЬЮ \r\nОТ 14 ТОНН СДАЮТСЯ В АРЕНДУ НА 2 И БОЛЕЕ СМЕН. ВОЗМОЖНА ДЛИТЕЛЬНАЯ КРУГЛОСУТОЧНАЯ АРЕНДА. ЭКОНОМИЧНЫЕ МОДЕЛИ ДЛЯ ЛЮБЫХ ВИДОВ СТРОИТЕЛЬНЫХ РАБОТ. КРАНЫ ЛЕГКО ЕЗДЯТ ПО БЕЗДОРОЖЬЮ И ПРОСТЫ В ЭКСПЛУАТАЦИИ. В НАШЕМ АВТОПАРКЕ ЕСТЬ АВТОКРАНЫ С РАЗНЫМ КОЛИЧЕСТВОМ РАБОЧИХ СКОРОСТЕЙ И ДЛИНОЙ ВЫЛЕТА РАБОЧЕЙ СТРЕЛЫ. \r\n\r\nМАШИНЫ ОБОРУДОВАНЫ НЕОБХОДИМЫМИ И СОВРЕМЕННЫМИ \r\nСРЕДСТВАМИ КОНТРОЛЯ И БЕЗОПАСНОСТИ. ПО ТРЕБОВАНИЮ СПЕЦТЕХНИКА СДАЕТСЯ В АРЕНДУ С ВОДИТЕЛЕМ-ОПЕРАТОРОМ И ТОПЛИВОМ, ВОЗМОЖНЫ УСЛУГИ БЕЗ СОЛЯРКИ ПО БОЛЕЕ НИЗКОЙ ЦЕНЕ. СТОИМОСТЬ АРЕНДЫ БУДЕТ СНИЖЕНА ПРИ ЗАКАЗЕ СПЕЦТЕХНИКИ НА 20 СУТОК И БОЛЕЕ. ОБРАТИТЕСЬ К МЕНЕДЖЕРУ ДЛЯ ОПЕРАТИВНОГО ОФОРМЛЕНИЯ ЗАКАЗА.','krany','413',NULL,NULL,NULL),(60,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,58,'Y','N',500,'Манипуляторы',400,4,5,2,'Аренда манипулятора подойдет тем, кто планирует перевозить контейнеры, ларьки, гаражи, строительные материалы, мусор и другие крупногабаритные грузы. Техника предоставляется вместе с водителями, чтобы вы не искали непрофессиональных рабочих на стороне. Если работы по перевозкам требуются вам постоянно, заключите с нами договор о долгосрочном сотрудничестве.<br>\n <br>\n Выбор&nbsp;манипулятора зависит от характера и объемов работ. Необходимо принимать во внимание грузоподъемность, вместительность кузова и длину стрелы. Если у вас возникнут проблемы с выбором – обратитесь к нашему менеджеру. Квалифицированный сотрудник быстро скоординирует вас по модельному ряду.<br>','html','МАНИПУЛЯТОРЫ\r\nАРЕНДА МАНИПУЛЯТОРА ПОДОЙДЕТ ТЕМ, КТО ПЛАНИРУЕТ \r\nПЕРЕВОЗИТЬ КОНТЕЙНЕРЫ, ЛАРЬКИ, ГАРАЖИ, СТРОИТЕЛЬНЫЕ МАТЕРИАЛЫ, МУСОР И ДРУГИЕ КРУПНОГАБАРИТНЫЕ ГРУЗЫ. ТЕХНИКА ПРЕДОСТАВЛЯЕТСЯ ВМЕСТЕ С ВОДИТЕЛЯМИ, ЧТОБЫ ВЫ НЕ ИСКАЛИ НЕПРОФЕССИОНАЛЬНЫХ РАБОЧИХ НА СТОРОНЕ. ЕСЛИ РАБОТЫ ПО ПЕРЕВОЗКАМ ТРЕБУЮТСЯ ВАМ ПОСТОЯННО, ЗАКЛЮЧИТЕ С НАМИ ДОГОВОР О ДОЛГОСРОЧНОМ СОТРУДНИЧЕСТВЕ.\r\n\r\nВЫБОР&NBSP;МАНИПУЛЯТОРА ЗАВИСИТ ОТ ХАРАКТЕРА \r\nИ ОБЪЕМОВ РАБОТ. НЕОБХОДИМО ПРИНИМАТЬ ВО ВНИМАНИЕ ГРУЗОПОДЪЕМНОСТЬ, ВМЕСТИТЕЛЬНОСТЬ КУЗОВА И ДЛИНУ СТРЕЛЫ. ЕСЛИ У ВАС ВОЗНИКНУТ ПРОБЛЕМЫ С ВЫБОРОМ – ОБРАТИТЕСЬ К НАШЕМУ МЕНЕДЖЕРУ. КВАЛИФИЦИРОВАННЫЙ СОТРУДНИК БЫСТРО СКООРДИНИРУЕТ ВАС ПО МОДЕЛЬНОМУ РЯДУ.','manipulyatory','414',NULL,NULL,NULL),(61,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,58,'Y','N',500,'Самосвалы',401,6,7,2,'Чаще всего самосвал используется для перевозки сыпучих строительных или промышленных грузов. В конструкции используется стальная платформа квадратного сечения с несущим каркасом. Также самосвал оснащен автоматическими запорами заднего борта, которые открываются при подъеме платформы. У машины электропневматическое управление подъемом, которое осуществляется из кабины. Имеется обогрев днища.<br>\n <br>\n Самосвалы для погрузочно-разгрузочных работ сдаются в аренду от 2х смен. Вездеходность и высокая грузоподъемность позволяют российским машинам быть отличными помощниками на строительной площадке. Представленные модели справятся с грузами до 30 тонн.&nbsp;<br>','html','САМОСВАЛЫ\r\nЧАЩЕ ВСЕГО САМОСВАЛ ИСПОЛЬЗУЕТСЯ ДЛЯ ПЕРЕВОЗКИ \r\nСЫПУЧИХ СТРОИТЕЛЬНЫХ ИЛИ ПРОМЫШЛЕННЫХ ГРУЗОВ. В КОНСТРУКЦИИ ИСПОЛЬЗУЕТСЯ СТАЛЬНАЯ ПЛАТФОРМА КВАДРАТНОГО СЕЧЕНИЯ С НЕСУЩИМ КАРКАСОМ. ТАКЖЕ САМОСВАЛ ОСНАЩЕН АВТОМАТИЧЕСКИМИ ЗАПОРАМИ ЗАДНЕГО БОРТА, КОТОРЫЕ ОТКРЫВАЮТСЯ ПРИ ПОДЪЕМЕ ПЛАТФОРМЫ. У МАШИНЫ ЭЛЕКТРОПНЕВМАТИЧЕСКОЕ УПРАВЛЕНИЕ ПОДЪЕМОМ, КОТОРОЕ ОСУЩЕСТВЛЯЕТСЯ ИЗ КАБИНЫ. ИМЕЕТСЯ ОБОГРЕВ ДНИЩА.\r\n\r\nСАМОСВАЛЫ ДЛЯ ПОГРУЗОЧНО-РАЗГРУЗОЧНЫХ \r\nРАБОТ СДАЮТСЯ В АРЕНДУ ОТ 2Х СМЕН. ВЕЗДЕХОДНОСТЬ И ВЫСОКАЯ ГРУЗОПОДЪЕМНОСТЬ ПОЗВОЛЯЮТ РОССИЙСКИМ МАШИНАМ БЫТЬ ОТЛИЧНЫМИ ПОМОЩНИКАМИ НА СТРОИТЕЛЬНОЙ ПЛОЩАДКЕ. ПРЕДСТАВЛЕННЫЕ МОДЕЛИ СПРАВЯТСЯ С ГРУЗАМИ ДО 30 ТОНН.&NBSP;','samosvaly','458',NULL,NULL,NULL),(62,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,58,'Y','N',500,'Экскаваторы',402,8,9,2,'В автопарке представлены гусеничные и колесные экскаваторы с разными размерами ковшей. В комплекте вы получаете необходимое навесное оборудование. Вы можете заказать спецтехнику сразу с дизельным топливом или с пустым баком. Доставим машину в любую точку города и области.<br>\n <br>\nСтандартные модели обычно применяются для выполнения строительных и земляных работ, более габаритные экскаваторы могут использоваться для более сложных проектов, например, решать задачи горнодобывающей промышленности. Экологичные двигатели нового поколения позволяют заботиться об окружающей среде.','html','ЭКСКАВАТОРЫ\r\nВ АВТОПАРКЕ ПРЕДСТАВЛЕНЫ ГУСЕНИЧНЫЕ И \r\nКОЛЕСНЫЕ ЭКСКАВАТОРЫ С РАЗНЫМИ РАЗМЕРАМИ КОВШЕЙ. В КОМПЛЕКТЕ ВЫ ПОЛУЧАЕТЕ НЕОБХОДИМОЕ НАВЕСНОЕ ОБОРУДОВАНИЕ. ВЫ МОЖЕТЕ ЗАКАЗАТЬ СПЕЦТЕХНИКУ СРАЗУ С ДИЗЕЛЬНЫМ ТОПЛИВОМ ИЛИ С ПУСТЫМ БАКОМ. ДОСТАВИМ МАШИНУ В ЛЮБУЮ ТОЧКУ ГОРОДА И ОБЛАСТИ.\r\n\r\nСТАНДАРТНЫЕ МОДЕЛИ ОБЫЧНО ПРИМЕНЯЮТСЯ \r\nДЛЯ ВЫПОЛНЕНИЯ СТРОИТЕЛЬНЫХ И ЗЕМЛЯНЫХ РАБОТ, БОЛЕЕ ГАБАРИТНЫЕ ЭКСКАВАТОРЫ МОГУТ ИСПОЛЬЗОВАТЬСЯ ДЛЯ БОЛЕЕ СЛОЖНЫХ ПРОЕКТОВ, НАПРИМЕР, РЕШАТЬ ЗАДАЧИ ГОРНОДОБЫВАЮЩЕЙ ПРОМЫШЛЕННОСТИ. ЭКОЛОГИЧНЫЕ ДВИГАТЕЛИ НОВОГО ПОКОЛЕНИЯ ПОЗВОЛЯЮТ ЗАБОТИТЬСЯ ОБ ОКРУЖАЮЩЕЙ СРЕДЕ.','varavayki','415',NULL,NULL,NULL),(63,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Медицинское оборудование',403,21,30,1,'Правильность постановки диагнозов и назначенного лечения зависит от функциональности и точности медицинского оборудования. Мы предлагаем современное и высокотехнологичное оборудование для государственных и частных учреждений здравоохранения. Работаем с лучшими российскими и зарубежными производителями. В нашей компании вы сможете заказать оборудование, мебель, косметологические приборы и высокоточную аппаратуру для лабораторий.<br>\n <br>\nОпытные инженеры компании «Олл Корп» произведут качественную и оперативную установку оборудования, наладку и запуск в эксплуатацию. Наши специалисты обязательно проведут инструктаж по пользованию и уходу за оборудованием. Если в процессе эксплуатации возникнет поломка, то инженеры компании быстро устранят ее и дадут гарантию на свою работу.','html','МЕДИЦИНСКОЕ ОБОРУДОВАНИЕ\r\nПРАВИЛЬНОСТЬ ПОСТАНОВКИ ДИАГНОЗОВ И НАЗНАЧЕННОГО \r\nЛЕЧЕНИЯ ЗАВИСИТ ОТ ФУНКЦИОНАЛЬНОСТИ И ТОЧНОСТИ МЕДИЦИНСКОГО ОБОРУДОВАНИЯ. МЫ ПРЕДЛАГАЕМ СОВРЕМЕННОЕ И ВЫСОКОТЕХНОЛОГИЧНОЕ ОБОРУДОВАНИЕ ДЛЯ ГОСУДАРСТВЕННЫХ И ЧАСТНЫХ УЧРЕЖДЕНИЙ ЗДРАВООХРАНЕНИЯ. РАБОТАЕМ С ЛУЧШИМИ РОССИЙСКИМИ И ЗАРУБЕЖНЫМИ ПРОИЗВОДИТЕЛЯМИ. В НАШЕЙ КОМПАНИИ ВЫ СМОЖЕТЕ ЗАКАЗАТЬ ОБОРУДОВАНИЕ, МЕБЕЛЬ, КОСМЕТОЛОГИЧЕСКИЕ ПРИБОРЫ И ВЫСОКОТОЧНУЮ АППАРАТУРУ ДЛЯ ЛАБОРАТОРИЙ.\r\n\r\nОПЫТНЫЕ ИНЖЕНЕРЫ КОМПАНИИ «ОЛЛ КОРП» ПРОИЗВЕДУТ \r\nКАЧЕСТВЕННУЮ И ОПЕРАТИВНУЮ УСТАНОВКУ ОБОРУДОВАНИЯ, НАЛАДКУ И ЗАПУСК В ЭКСПЛУАТАЦИЮ. НАШИ СПЕЦИАЛИСТЫ ОБЯЗАТЕЛЬНО ПРОВЕДУТ ИНСТРУКТАЖ ПО ПОЛЬЗОВАНИЮ И УХОДУ ЗА ОБОРУДОВАНИЕМ. ЕСЛИ В ПРОЦЕССЕ ЭКСПЛУАТАЦИИ ВОЗНИКНЕТ ПОЛОМКА, ТО ИНЖЕНЕРЫ КОМПАНИИ БЫСТРО УСТРАНЯТ ЕЕ И ДАДУТ ГАРАНТИЮ НА СВОЮ РАБОТУ.','meditsinskoe-oborudovanie','471',NULL,NULL,NULL),(64,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,63,'Y','N',500,'Косметология',404,22,23,2,'Современная косметология решает многие проблемы со здоровьем, которые сказываются на внешности человека. Эта сфера позволяет делать человеческое лицо привлекательнее и надолго сохранять его молодость и свежесть. В последнее время в эстетических центрах все чаще прибегают к аппаратной косметологии. В ней используются специальные устройства интенсивного воздействия, вызывая благотворное влияние на эстетически приятный вид лица и тела.<br>\n <br>\nЕсли вы планируете открыть косметологический кабинет, то именно аппаратная косметология станет незаменим помощником при достижении целей. Наше высококачественное оборудование сделано из гиппоалергенных материалов, но при этом прочное и готово к долгому сроку эксплуатации. А новейшие технологии помогут эффективно бороться с недостатками человеческого тела.','html','КОСМЕТОЛОГИЯ\r\nСОВРЕМЕННАЯ КОСМЕТОЛОГИЯ РЕШАЕТ МНОГИЕ \r\nПРОБЛЕМЫ СО ЗДОРОВЬЕМ, КОТОРЫЕ СКАЗЫВАЮТСЯ НА ВНЕШНОСТИ ЧЕЛОВЕКА. ЭТА СФЕРА ПОЗВОЛЯЕТ ДЕЛАТЬ ЧЕЛОВЕЧЕСКОЕ ЛИЦО ПРИВЛЕКАТЕЛЬНЕЕ И НАДОЛГО СОХРАНЯТЬ ЕГО МОЛОДОСТЬ И СВЕЖЕСТЬ. В ПОСЛЕДНЕЕ ВРЕМЯ В ЭСТЕТИЧЕСКИХ ЦЕНТРАХ ВСЕ ЧАЩЕ ПРИБЕГАЮТ К АППАРАТНОЙ КОСМЕТОЛОГИИ. В НЕЙ ИСПОЛЬЗУЮТСЯ СПЕЦИАЛЬНЫЕ УСТРОЙСТВА ИНТЕНСИВНОГО ВОЗДЕЙСТВИЯ, ВЫЗЫВАЯ БЛАГОТВОРНОЕ ВЛИЯНИЕ НА ЭСТЕТИЧЕСКИ ПРИЯТНЫЙ ВИД ЛИЦА И ТЕЛА.\r\n\r\nЕСЛИ ВЫ ПЛАНИРУЕТЕ ОТКРЫТЬ КОСМЕТОЛОГИЧЕСКИЙ \r\nКАБИНЕТ, ТО ИМЕННО АППАРАТНАЯ КОСМЕТОЛОГИЯ СТАНЕТ НЕЗАМЕНИМ ПОМОЩНИКОМ ПРИ ДОСТИЖЕНИИ ЦЕЛЕЙ. НАШЕ ВЫСОКОКАЧЕСТВЕННОЕ ОБОРУДОВАНИЕ СДЕЛАНО ИЗ ГИППОАЛЕРГЕННЫХ МАТЕРИАЛОВ, НО ПРИ ЭТОМ ПРОЧНОЕ И ГОТОВО К ДОЛГОМУ СРОКУ ЭКСПЛУАТАЦИИ. А НОВЕЙШИЕ ТЕХНОЛОГИИ ПОМОГУТ ЭФФЕКТИВНО БОРОТЬСЯ С НЕДОСТАТКАМИ ЧЕЛОВЕЧЕСКОГО ТЕЛА.','kosmetologiya','472',NULL,NULL,NULL),(65,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,63,'Y','N',500,'Лаборатория',405,24,25,2,'Компания «Олл Корп» предлагает оборудование для оснащения лабораторий любой направленности. Качество нашей продукции соответствует требованиям международных и Российских стандартов, что стало результатом многоступенчатой системы контроля производства. <br>\n <br>\nВысококачественное лабораторное оборудование – залог успешной работы во всех областях аналитической, исследовательской работы, промышленности и производства, поэтому мы предоставляем не только лабораторное оборудование, но и сервисное обслуживание поставляемой продукции.','html','ЛАБОРАТОРИЯ\r\nКОМПАНИЯ «ОЛЛ КОРП» ПРЕДЛАГАЕТ ОБОРУДОВАНИЕ \r\nДЛЯ ОСНАЩЕНИЯ ЛАБОРАТОРИЙ ЛЮБОЙ НАПРАВЛЕННОСТИ. КАЧЕСТВО НАШЕЙ ПРОДУКЦИИ СООТВЕТСТВУЕТ ТРЕБОВАНИЯМ МЕЖДУНАРОДНЫХ И РОССИЙСКИХ СТАНДАРТОВ, ЧТО СТАЛО РЕЗУЛЬТАТОМ МНОГОСТУПЕНЧАТОЙ СИСТЕМЫ КОНТРОЛЯ ПРОИЗВОДСТВА. \r\n\r\nВЫСОКОКАЧЕСТВЕННОЕ ЛАБОРАТОРНОЕ ОБОРУДОВАНИЕ \r\n– ЗАЛОГ УСПЕШНОЙ РАБОТЫ ВО ВСЕХ ОБЛАСТЯХ АНАЛИТИЧЕСКОЙ, ИССЛЕДОВАТЕЛЬСКОЙ РАБОТЫ, ПРОМЫШЛЕННОСТИ И ПРОИЗВОДСТВА, ПОЭТОМУ МЫ ПРЕДОСТАВЛЯЕМ НЕ ТОЛЬКО ЛАБОРАТОРНОЕ ОБОРУДОВАНИЕ, НО И СЕРВИСНОЕ ОБСЛУЖИВАНИЕ ПОСТАВЛЯЕМОЙ ПРОДУКЦИИ.','laboratoriya','474',NULL,NULL,NULL),(66,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,63,'Y','N',500,'Медицинская мебель',406,26,27,2,'Мебель является важной составляющей при работе учреждений здравоохранения. Она влияет на комфорт пациентов при осмотре, сохранность различных медицинских принадлежностей и чистоту в кабинете и эстетический вид помещения.<br>\n <br>\n Из-за постоянного использования дезинфицирующих средств и сильных химикатов к мебели предъявляются особые требования по устойчивости к постоянному механическому воздействию и влиянию агрессивных химических средств. Компания «Олл Корп» работает только с проверенными поставщиками, поэтому в нашем каталоге представлены высококачественные товары.','html','МЕДИЦИНСКАЯ МЕБЕЛЬ\r\nМЕБЕЛЬ ЯВЛЯЕТСЯ ВАЖНОЙ СОСТАВЛЯЮЩЕЙ ПРИ \r\nРАБОТЕ УЧРЕЖДЕНИЙ ЗДРАВООХРАНЕНИЯ. ОНА ВЛИЯЕТ НА КОМФОРТ ПАЦИЕНТОВ ПРИ ОСМОТРЕ, СОХРАННОСТЬ РАЗЛИЧНЫХ МЕДИЦИНСКИХ ПРИНАДЛЕЖНОСТЕЙ И ЧИСТОТУ В КАБИНЕТЕ И ЭСТЕТИЧЕСКИЙ ВИД ПОМЕЩЕНИЯ.\r\n\r\nИЗ-ЗА ПОСТОЯННОГО ИСПОЛЬЗОВАНИЯ ДЕЗИНФИЦИРУЮЩИХ \r\nСРЕДСТВ И СИЛЬНЫХ ХИМИКАТОВ К МЕБЕЛИ ПРЕДЪЯВЛЯЮТСЯ ОСОБЫЕ ТРЕБОВАНИЯ ПО УСТОЙЧИВОСТИ К ПОСТОЯННОМУ МЕХАНИЧЕСКОМУ ВОЗДЕЙСТВИЮ И ВЛИЯНИЮ АГРЕССИВНЫХ ХИМИЧЕСКИХ СРЕДСТВ. КОМПАНИЯ «ОЛЛ КОРП» РАБОТАЕТ ТОЛЬКО С ПРОВЕРЕННЫМИ ПОСТАВЩИКАМИ, ПОЭТОМУ В НАШЕМ КАТАЛОГЕ ПРЕДСТАВЛЕНЫ ВЫСОКОКАЧЕСТВЕННЫЕ ТОВАРЫ.','meditsinskaya-mebel','473',NULL,NULL,NULL),(67,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,63,'Y','N',500,'Рентгеновские аппараты',407,28,29,2,'Среди представленного оборудования в компании «Олл Корп» вы можете выбрать рентгенаппарат, который будет подходить под поставленные задачи. Выберите стационарное, передвижное или мобильное устройство, чтобы облегчить работу лечебно-профилактического учреждения. Каждый рентгеновский аппарат из нашего магазина сертифицирован и соответствует стандартам государственных учреждений. <br>\n <br>\nВсе аппараты просты в использовании и безопасны для сотрудников ЛПУ и его пациентов. Вне зависимости от части тела или органа, на котором будет проводиться исследование, наши аппараты сделают качественный снимок и помогут при постановке диагноза. Низкие показатели облучения и высокий порог надежности обеспечат эффективность проведения рентгенологических исследований.','html','РЕНТГЕНОВСКИЕ АППАРАТЫ\r\nСРЕДИ ПРЕДСТАВЛЕННОГО ОБОРУДОВАНИЯ В КОМПАНИИ \r\n«ОЛЛ КОРП» ВЫ МОЖЕТЕ ВЫБРАТЬ РЕНТГЕНАППАРАТ, КОТОРЫЙ БУДЕТ ПОДХОДИТЬ ПОД ПОСТАВЛЕННЫЕ ЗАДАЧИ. ВЫБЕРИТЕ СТАЦИОНАРНОЕ, ПЕРЕДВИЖНОЕ ИЛИ МОБИЛЬНОЕ УСТРОЙСТВО, ЧТОБЫ ОБЛЕГЧИТЬ РАБОТУ ЛЕЧЕБНО-ПРОФИЛАКТИЧЕСКОГО УЧРЕЖДЕНИЯ. КАЖДЫЙ РЕНТГЕНОВСКИЙ АППАРАТ ИЗ НАШЕГО МАГАЗИНА СЕРТИФИЦИРОВАН И СООТВЕТСТВУЕТ СТАНДАРТАМ ГОСУДАРСТВЕННЫХ УЧРЕЖДЕНИЙ. \r\n\r\nВСЕ АППАРАТЫ ПРОСТЫ В ИСПОЛЬЗОВАНИИ И БЕЗОПАСНЫ \r\nДЛЯ СОТРУДНИКОВ ЛПУ И ЕГО ПАЦИЕНТОВ. ВНЕ ЗАВИСИМОСТИ ОТ ЧАСТИ ТЕЛА ИЛИ ОРГАНА, НА КОТОРОМ БУДЕТ ПРОВОДИТЬСЯ ИССЛЕДОВАНИЕ, НАШИ АППАРАТЫ СДЕЛАЮТ КАЧЕСТВЕННЫЙ СНИМОК И ПОМОГУТ ПРИ ПОСТАНОВКЕ ДИАГНОЗА. НИЗКИЕ ПОКАЗАТЕЛИ ОБЛУЧЕНИЯ И ВЫСОКИЙ ПОРОГ НАДЕЖНОСТИ ОБЕСПЕЧАТ ЭФФЕКТИВНОСТЬ ПРОВЕДЕНИЯ РЕНТГЕНОЛОГИЧЕСКИХ ИССЛЕДОВАНИЙ.','rentgenovskie-apparaty','484',NULL,NULL,NULL),(68,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Металлопрокат',408,31,40,1,'Компания «Олл Корп» оптом и в розницу поставляет металлопрокат для промышленных предприятий. На складе компании всегда в наличии востребованные изделия металлопроката высокого качества. Металлопрокат используют в строительной сфере, сельском хозяйстве, промышленном производстве и других сферах<br>\n<br>\nМы изготавливаем детали из чугуна, стали, меди и других металлов, а также сплавов. Предлагаем изделия холодной и горячей катки из черных и цветных металлов. В нашем каталоге вы найдете листовой, трубный и сортовой металлопрокат. Крупнейшая металлобаза в городе позволяет нам выполнять заказы лидеров металлообработки в заданный срок.','html','МЕТАЛЛОПРОКАТ\r\nКОМПАНИЯ «ОЛЛ КОРП» ОПТОМ И В РОЗНИЦУ ПОСТАВЛЯЕТ \r\nМЕТАЛЛОПРОКАТ ДЛЯ ПРОМЫШЛЕННЫХ ПРЕДПРИЯТИЙ. НА СКЛАДЕ КОМПАНИИ ВСЕГДА В НАЛИЧИИ ВОСТРЕБОВАННЫЕ ИЗДЕЛИЯ МЕТАЛЛОПРОКАТА ВЫСОКОГО КАЧЕСТВА. МЕТАЛЛОПРОКАТ ИСПОЛЬЗУЮТ В СТРОИТЕЛЬНОЙ СФЕРЕ, СЕЛЬСКОМ ХОЗЯЙСТВЕ, ПРОМЫШЛЕННОМ ПРОИЗВОДСТВЕ И ДРУГИХ СФЕРАХ\r\n\r\nМЫ ИЗГОТАВЛИВАЕМ ДЕТАЛИ ИЗ ЧУГУНА, СТАЛИ, \r\nМЕДИ И ДРУГИХ МЕТАЛЛОВ, А ТАКЖЕ СПЛАВОВ. ПРЕДЛАГАЕМ ИЗДЕЛИЯ ХОЛОДНОЙ И ГОРЯЧЕЙ КАТКИ ИЗ ЧЕРНЫХ И ЦВЕТНЫХ МЕТАЛЛОВ. В НАШЕМ КАТАЛОГЕ ВЫ НАЙДЕТЕ ЛИСТОВОЙ, ТРУБНЫЙ И СОРТОВОЙ МЕТАЛЛОПРОКАТ. КРУПНЕЙШАЯ МЕТАЛЛОБАЗА В ГОРОДЕ ПОЗВОЛЯЕТ НАМ ВЫПОЛНЯТЬ ЗАКАЗЫ ЛИДЕРОВ МЕТАЛЛООБРАБОТКИ В ЗАДАННЫЙ СРОК.','metalloprokat','412',NULL,NULL,NULL),(69,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,68,'Y','N',100,'Сортовой прокат из нержавеющей стали',409,32,33,2,'Сортовой прокат – это изделия из металла различных сплошных поперечных сечений, конечный продукт горячекатных станов. Чтобы получить сортовой прокат нагретые слитки металла обжимают между валками прокатного стана. Форма валков влияет на форму поперечного сечения проката. При работе на гладких валках получается лист или полоса, а если есть полукруглые канавки, то выходит прокат круглого сечения и так далее. <br>\n <br>\n Сортовой прокат – это полуфабрикат, который доводят до готовой продукции на токарном, фрезерном и другом оборудовании. В необработанном виде прокат используется при возведении металлоконструкций. Компания «Олл Корп» продает сортовой прокат из высокоуглеродистой стали. Вы можете заказать прокат высокой, повышенной и обычной точности. Если есть необходимость получить необычную форму поперечного сечения – обратитесь к нашему менеджеру.<br>','html','СОРТОВОЙ ПРОКАТ ИЗ НЕРЖАВЕЮЩЕЙ СТАЛИ\r\nСОРТОВОЙ ПРОКАТ – ЭТО ИЗДЕЛИЯ ИЗ МЕТАЛЛА \r\nРАЗЛИЧНЫХ СПЛОШНЫХ ПОПЕРЕЧНЫХ СЕЧЕНИЙ, КОНЕЧНЫЙ ПРОДУКТ ГОРЯЧЕКАТНЫХ СТАНОВ. ЧТОБЫ ПОЛУЧИТЬ СОРТОВОЙ ПРОКАТ НАГРЕТЫЕ СЛИТКИ МЕТАЛЛА ОБЖИМАЮТ МЕЖДУ ВАЛКАМИ ПРОКАТНОГО СТАНА. ФОРМА ВАЛКОВ ВЛИЯЕТ НА ФОРМУ ПОПЕРЕЧНОГО СЕЧЕНИЯ ПРОКАТА. ПРИ РАБОТЕ НА ГЛАДКИХ ВАЛКАХ ПОЛУЧАЕТСЯ ЛИСТ ИЛИ ПОЛОСА, А ЕСЛИ ЕСТЬ ПОЛУКРУГЛЫЕ КАНАВКИ, ТО ВЫХОДИТ ПРОКАТ КРУГЛОГО СЕЧЕНИЯ И ТАК ДАЛЕЕ. \r\n\r\nСОРТОВОЙ ПРОКАТ – ЭТО ПОЛУФАБРИКАТ, КОТОРЫЙ \r\nДОВОДЯТ ДО ГОТОВОЙ ПРОДУКЦИИ НА ТОКАРНОМ, ФРЕЗЕРНОМ И ДРУГОМ ОБОРУДОВАНИИ. В НЕОБРАБОТАННОМ ВИДЕ ПРОКАТ ИСПОЛЬЗУЕТСЯ ПРИ ВОЗВЕДЕНИИ МЕТАЛЛОКОНСТРУКЦИЙ. КОМПАНИЯ «ОЛЛ КОРП» ПРОДАЕТ СОРТОВОЙ ПРОКАТ ИЗ ВЫСОКОУГЛЕРОДИСТОЙ СТАЛИ. ВЫ МОЖЕТЕ ЗАКАЗАТЬ ПРОКАТ ВЫСОКОЙ, ПОВЫШЕННОЙ И ОБЫЧНОЙ ТОЧНОСТИ. ЕСЛИ ЕСТЬ НЕОБХОДИМОСТЬ ПОЛУЧИТЬ НЕОБЫЧНУЮ ФОРМУ ПОПЕРЕЧНОГО СЕЧЕНИЯ – ОБРАТИТЕСЬ К НАШЕМУ МЕНЕДЖЕРУ.','sortovoy-prokat-iz-nerzhaveyushchey-stali','463',NULL,NULL,NULL),(70,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,68,'Y','N',200,'Трубы нержавеющие',410,34,35,2,'Предлагаем трубы производства разных стран из долговечного материала – коррозионностойкой нержавеющей стали. В зависимости от будущего воздействия при выборе трубы обращайте внимание на марку стали, форму сечения и метод изготовления – от этого будет зависеть срок эксплуатации изделия. <br>\n <br>\n Существует три основных способа производства нержавеющих стальных труб:<br>\n <br>\n<ul>\n	<li>свертывание штрипса и пропайка шва медью, в результате получаются паяные свернутые трубы</li>\n	<li>\n	горячее деформирование, холодное деформирование и метод центробежного литья используются при изготовлении бесшовных труб</li>\n	<li>\n	с помощью лазерной, плазменной и электро-лучевой сварки производятся сварные трубы.</li>\n</ul>\n Свяжитесь с нашим менеджером, чтобы правильно подобрать изделие и договориться о сроках доставки.<br>\n <br>\n <br>','html','ТРУБЫ НЕРЖАВЕЮЩИЕ\r\nПРЕДЛАГАЕМ ТРУБЫ ПРОИЗВОДСТВА РАЗНЫХ СТРАН \r\nИЗ ДОЛГОВЕЧНОГО МАТЕРИАЛА – КОРРОЗИОННОСТОЙКОЙ НЕРЖАВЕЮЩЕЙ СТАЛИ. В ЗАВИСИМОСТИ ОТ БУДУЩЕГО ВОЗДЕЙСТВИЯ ПРИ ВЫБОРЕ ТРУБЫ ОБРАЩАЙТЕ ВНИМАНИЕ НА МАРКУ СТАЛИ, ФОРМУ СЕЧЕНИЯ И МЕТОД ИЗГОТОВЛЕНИЯ – ОТ ЭТОГО БУДЕТ ЗАВИСЕТЬ СРОК ЭКСПЛУАТАЦИИ ИЗДЕЛИЯ. \r\n\r\nСУЩЕСТВУЕТ ТРИ ОСНОВНЫХ СПОСОБА ПРОИЗВОДСТВА \r\nНЕРЖАВЕЮЩИХ СТАЛЬНЫХ ТРУБ:\r\n\r\n\r\n\r\n- СВЕРТЫВАНИЕ ШТРИПСА И ПРОПАЙКА ШВА МЕДЬЮ, \r\nВ РЕЗУЛЬТАТЕ ПОЛУЧАЮТСЯ ПАЯНЫЕ СВЕРНУТЫЕ ТРУБЫ \r\n- ГОРЯЧЕЕ ДЕФОРМИРОВАНИЕ, ХОЛОДНОЕ ДЕФОРМИРОВАНИЕ \r\nИ МЕТОД ЦЕНТРОБЕЖНОГО ЛИТЬЯ ИСПОЛЬЗУЮТСЯ ПРИ ИЗГОТОВЛЕНИИ БЕСШОВНЫХ ТРУБ \r\n- С ПОМОЩЬЮ ЛАЗЕРНОЙ, ПЛАЗМЕННОЙ И ЭЛЕКТРО-ЛУЧЕВОЙ \r\nСВАРКИ ПРОИЗВОДЯТСЯ СВАРНЫЕ ТРУБЫ. СВЯЖИТЕСЬ С НАШИМ МЕНЕДЖЕРОМ, ЧТОБЫ ПРАВИЛЬНО ПОДОБРАТЬ ИЗДЕЛИЕ И ДОГОВОРИТЬСЯ О СРОКАХ ДОСТАВКИ.','truby-nerzhaveyushchie','462',NULL,NULL,NULL),(71,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,68,'Y','N',300,'Сварочные материалы',411,36,37,2,'Компания «Олл Корп» предлагает материалы, требуемые для сварки изделий. Сварочные материалы обеспечивают определённые химические свойства наплавленного металла,получение сварных беспористых швов, устойчивых к образованию трещин, а также экономичность сварки.','html','СВАРОЧНЫЕ МАТЕРИАЛЫ\r\nКОМПАНИЯ «ОЛЛ КОРП» ПРЕДЛАГАЕТ МАТЕРИАЛЫ, \r\nТРЕБУЕМЫЕ ДЛЯ СВАРКИ ИЗДЕЛИЙ. СВАРОЧНЫЕ МАТЕРИАЛЫ ОБЕСПЕЧИВАЮТ ОПРЕДЕЛЁННЫЕ ХИМИЧЕСКИЕ СВОЙСТВА НАПЛАВЛЕННОГО МЕТАЛЛА,ПОЛУЧЕНИЕ СВАРНЫХ БЕСПОРИСТЫХ ШВОВ, УСТОЙЧИВЫХ К ОБРАЗОВАНИЮ ТРЕЩИН, А ТАКЖЕ ЭКОНОМИЧНОСТЬ СВАРКИ.','svarochnye-materialy','464',NULL,NULL,NULL),(72,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,68,'Y','N',400,'Просечно-вытяжные листы',412,38,39,2,'Просечно-вытяжной лист (лист ПВЛ) – востребованное изделие металлопроката. Лист ПВЛ представляет металлическую сетку-пластину, которая поставляется в рулонах. Изготавливается из листового проката по методу просечки и вытяжки. По ГОСТу просечно-вытяжной лист должен проходить обработку специальными ножами – просечку, а после этого вытягиваться на вытяжном станке.<br>\n <br>\nБлагодаря прочности и легкости конструкции и просечно-вытяжные листы используются в в народном хозяйстве, при ремонтно-строительных работах, в топливной и добывающей промышленности, машиностроении и даже дизайнерской отделке помещений.','html','ПРОСЕЧНО-ВЫТЯЖНЫЕ ЛИСТЫ\r\nПРОСЕЧНО-ВЫТЯЖНОЙ ЛИСТ (ЛИСТ ПВЛ) – ВОСТРЕБОВАННОЕ \r\nИЗДЕЛИЕ МЕТАЛЛОПРОКАТА. ЛИСТ ПВЛ ПРЕДСТАВЛЯЕТ МЕТАЛЛИЧЕСКУЮ СЕТКУ-ПЛАСТИНУ, КОТОРАЯ ПОСТАВЛЯЕТСЯ В РУЛОНАХ. ИЗГОТАВЛИВАЕТСЯ ИЗ ЛИСТОВОГО ПРОКАТА ПО МЕТОДУ ПРОСЕЧКИ И ВЫТЯЖКИ. ПО ГОСТУ ПРОСЕЧНО-ВЫТЯЖНОЙ ЛИСТ ДОЛЖЕН ПРОХОДИТЬ ОБРАБОТКУ СПЕЦИАЛЬНЫМИ НОЖАМИ – ПРОСЕЧКУ, А ПОСЛЕ ЭТОГО ВЫТЯГИВАТЬСЯ НА ВЫТЯЖНОМ СТАНКЕ.\r\n\r\nБЛАГОДАРЯ ПРОЧНОСТИ И ЛЕГКОСТИ КОНСТРУКЦИИ \r\nИ ПРОСЕЧНО-ВЫТЯЖНЫЕ ЛИСТЫ ИСПОЛЬЗУЮТСЯ В В НАРОДНОМ ХОЗЯЙСТВЕ, ПРИ РЕМОНТНО-СТРОИТЕЛЬНЫХ РАБОТАХ, В ТОПЛИВНОЙ И ДОБЫВАЮЩЕЙ ПРОМЫШЛЕННОСТИ, МАШИНОСТРОЕНИИ И ДАЖЕ ДИЗАЙНЕРСКОЙ ОТДЕЛКЕ ПОМЕЩЕНИЙ.','prosechno-vytyazhnye-listy','461',NULL,NULL,NULL),(73,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Программные продукты',413,43,52,1,'Программный продукт – это программа, которую можно использовать в личных целях на разных компьютерах независимо от разработчиков. Компания «Олл Корп» предлагает программные продукты для эффективной работы организация, контроля и учета информации. Ко всем программам прилагается документация, которая раскрывает возможности, разъясняет порядок работы, настройки и внутреннего устройства продукта. Применение лицензионных программных продуктов облегчает работу компании.','html','ПРОГРАММНЫЕ ПРОДУКТЫ\r\nПРОГРАММНЫЙ ПРОДУКТ – ЭТО ПРОГРАММА, КОТОРУЮ \r\nМОЖНО ИСПОЛЬЗОВАТЬ В ЛИЧНЫХ ЦЕЛЯХ НА РАЗНЫХ КОМПЬЮТЕРАХ НЕЗАВИСИМО ОТ РАЗРАБОТЧИКОВ. КОМПАНИЯ «ОЛЛ КОРП» ПРЕДЛАГАЕТ ПРОГРАММНЫЕ ПРОДУКТЫ ДЛЯ ЭФФЕКТИВНОЙ РАБОТЫ ОРГАНИЗАЦИЯ, КОНТРОЛЯ И УЧЕТА ИНФОРМАЦИИ. КО ВСЕМ ПРОГРАММАМ ПРИЛАГАЕТСЯ ДОКУМЕНТАЦИЯ, КОТОРАЯ РАСКРЫВАЕТ ВОЗМОЖНОСТИ, РАЗЪЯСНЯЕТ ПОРЯДОК РАБОТЫ, НАСТРОЙКИ И ВНУТРЕННЕГО УСТРОЙСТВА ПРОДУКТА. ПРИМЕНЕНИЕ ЛИЦЕНЗИОННЫХ ПРОГРАММНЫХ ПРОДУКТОВ ОБЛЕГЧАЕТ РАБОТУ КОМПАНИИ.','programmnye-produkty','406',NULL,NULL,NULL),(74,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,73,'Y','N',1,'CRM системы',414,44,45,2,'<p>\n <b>CRM-система</b> — корпоративная информационная система и незаменимый &nbsp;инструмент для ведения бизнеса. В CRM-системе вы можете управлять бизнес-процессами: проектами, клиентами, ресурсами, финансами и счетами.\n</p>\n<p>\n <b>Преимущества CRM систем:</b>\n</p>\n<ul>\n	<li>Множество инструментов управления компанией в одной программе<br>\n </li>\n</ul>\n Продвинутые CRM позволяют управлять всеми составляющими бизнеса — проектами, персоналом, учетом клиентов, коммуникациями, финансами, документооборотом, временем, сайтом, рассылками и др. &nbsp;<br>\n<ul>\n</ul>\n<ul>\n	<li>\n	<p>\n		 Все данные – в одном месте\n	</p>\n </li>\n</ul>\n<p>\n	 Хорошая CRM умеет хранить все данные по проектам, клиентам, контактам в одном месте. Вся информация всегда под рукой у каждого из сотрудников. Быстрый доступ к данным позволяет оперативно обслуживать клиентов.\n</p>\n<ul>\n	<li>\n	<p>\n		 Оптимизация работы персонала\n	</p>\n </li>\n</ul>\n<p>\n	 Работа через CRM позволяет увидеть, кто из сотрудников чем занят, какая у кого нагрузка и насколько эффективен каждый работник. Вы можете назначить задачи сотрудникам на сегодня, на завтра и на следующую неделю. Тайм-трекер рассчитает затраченное время на проекты до секунды.\n</p>\n<ul>\n	<li>\n	<p>\n		 Аналитика по продажам\n	</p>\n </li>\n</ul>\n<p>\n	 CRM позволяет автоматически строить воронки продаж, графики и диаграммы, помогая&nbsp;отследить ход продаж в динамике и вовремя заметить те направления, на которых нужны корректировки.\n</p>\n<ul>\n	<li>\n	<p>\n		 Отправка и отслеживание счетов\n	</p>\n </li>\n</ul>\nВы можете привязывать счета к проекту, сделке, контрагенту и отправлять клиенту от имени нужной организации. А когда клиент оплатит счет, вы увидите это в системе.','html','CRM СИСТЕМЫ\r\nCRM-СИСТЕМА — КОРПОРАТИВНАЯ ИНФОРМАЦИОННАЯ \r\nСИСТЕМА И НЕЗАМЕНИМЫЙ &NBSP;ИНСТРУМЕНТ ДЛЯ ВЕДЕНИЯ БИЗНЕСА. В CRM-СИСТЕМЕ ВЫ МОЖЕТЕ УПРАВЛЯТЬ БИЗНЕС-ПРОЦЕССАМИ: ПРОЕКТАМИ, КЛИЕНТАМИ, РЕСУРСАМИ, ФИНАНСАМИ И СЧЕТАМИ. \r\n\r\nПРЕИМУЩЕСТВА CRM СИСТЕМ: \r\n\r\n- МНОЖЕСТВО ИНСТРУМЕНТОВ УПРАВЛЕНИЯ КОМПАНИЕЙ \r\nВ ОДНОЙ ПРОГРАММЕ\r\n ПРОДВИНУТЫЕ CRM ПОЗВОЛЯЮТ УПРАВЛЯТЬ ВСЕМИ \r\nСОСТАВЛЯЮЩИМИ БИЗНЕСА — ПРОЕКТАМИ, ПЕРСОНАЛОМ, УЧЕТОМ КЛИЕНТОВ, КОММУНИКАЦИЯМИ, ФИНАНСАМИ, ДОКУМЕНТООБОРОТОМ, ВРЕМЕНЕМ, САЙТОМ, РАССЫЛКАМИ И ДР. &NBSP;\r\n\r\n \r\n\r\n- \r\n\r\nВСЕ ДАННЫЕ – В ОДНОМ МЕСТЕ \r\n\r\nХОРОШАЯ CRM УМЕЕТ ХРАНИТЬ ВСЕ ДАННЫЕ ПО ПРОЕКТАМ, \r\nКЛИЕНТАМ, КОНТАКТАМ В ОДНОМ МЕСТЕ. ВСЯ ИНФОРМАЦИЯ ВСЕГДА ПОД РУКОЙ У КАЖДОГО ИЗ СОТРУДНИКОВ. БЫСТРЫЙ ДОСТУП К ДАННЫМ ПОЗВОЛЯЕТ ОПЕРАТИВНО ОБСЛУЖИВАТЬ КЛИЕНТОВ. \r\n\r\n- \r\n\r\nОПТИМИЗАЦИЯ РАБОТЫ ПЕРСОНАЛА \r\n\r\nРАБОТА ЧЕРЕЗ CRM ПОЗВОЛЯЕТ УВИДЕТЬ, КТО ИЗ \r\nСОТРУДНИКОВ ЧЕМ ЗАНЯТ, КАКАЯ У КОГО НАГРУЗКА И НАСКОЛЬКО ЭФФЕКТИВЕН КАЖДЫЙ РАБОТНИК. ВЫ МОЖЕТЕ НАЗНАЧИТЬ ЗАДАЧИ СОТРУДНИКАМ НА СЕГОДНЯ, НА ЗАВТРА И НА СЛЕДУЮЩУЮ НЕДЕЛЮ. ТАЙМ-ТРЕКЕР РАССЧИТАЕТ ЗАТРАЧЕННОЕ ВРЕМЯ НА ПРОЕКТЫ ДО СЕКУНДЫ. \r\n\r\n- \r\n\r\nАНАЛИТИКА ПО ПРОДАЖАМ \r\n\r\nCRM ПОЗВОЛЯЕТ АВТОМАТИЧЕСКИ СТРОИТЬ ВОРОНКИ \r\nПРОДАЖ, ГРАФИКИ И ДИАГРАММЫ, ПОМОГАЯ&NBSP;ОТСЛЕДИТЬ ХОД ПРОДАЖ В ДИНАМИКЕ И ВОВРЕМЯ ЗАМЕТИТЬ ТЕ НАПРАВЛЕНИЯ, НА КОТОРЫХ НУЖНЫ КОРРЕКТИРОВКИ. \r\n\r\n- \r\n\r\nОТПРАВКА И ОТСЛЕЖИВАНИЕ СЧЕТОВ ВЫ МОЖЕТЕ \r\nПРИВЯЗЫВАТЬ СЧЕТА К ПРОЕКТУ, СДЕЛКЕ, КОНТРАГЕНТУ И ОТПРАВЛЯТЬ КЛИЕНТУ ОТ ИМЕНИ НУЖНОЙ ОРГАНИЗАЦИИ. А КОГДА КЛИЕНТ ОПЛАТИТ СЧЕТ, ВЫ УВИДИТЕ ЭТО В СИСТЕМЕ.','crm-sistemy','20',NULL,415,NULL),(75,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,73,'Y','N',100,'Хостинг',416,46,47,2,'<p>\n	 Выбрать надежный хостинг — все равно&nbsp;что заложить крепкий и надежный фундамент для дома. Пока он стоит и стабильно работает, никто и не задумается о его существовании. &nbsp;Но стоит только появиться проблемам, как хостинг выходит на первый план. Сайт начинает безбожно виснуть, скорость загрузки страниц увеличивается до 5 минут, а базы данных вообще не подгружают заявки с сайта.\n</p>\n<p>\n	 Хостинг является неотъемлемой частью любого веб-проекта. От хостинга зависит скорость загрузки страниц, производительность сайта, безопасность и целостность ресурсов.\n</p>\n Наша компания сотрудничает с ведущими хостингами, которые идеально подойдут для проектов на&nbsp;1С-Битрикс и других CMS.\n<p>\n</p>','html','ХОСТИНГ\r\nВЫБРАТЬ НАДЕЖНЫЙ ХОСТИНГ — ВСЕ РАВНО&NBSP;ЧТО \r\nЗАЛОЖИТЬ КРЕПКИЙ И НАДЕЖНЫЙ ФУНДАМЕНТ ДЛЯ ДОМА. ПОКА ОН СТОИТ И СТАБИЛЬНО РАБОТАЕТ, НИКТО И НЕ ЗАДУМАЕТСЯ О ЕГО СУЩЕСТВОВАНИИ. &NBSP;НО СТОИТ ТОЛЬКО ПОЯВИТЬСЯ ПРОБЛЕМАМ, КАК ХОСТИНГ ВЫХОДИТ НА ПЕРВЫЙ ПЛАН. САЙТ НАЧИНАЕТ БЕЗБОЖНО ВИСНУТЬ, СКОРОСТЬ ЗАГРУЗКИ СТРАНИЦ УВЕЛИЧИВАЕТСЯ ДО 5 МИНУТ, А БАЗЫ ДАННЫХ ВООБЩЕ НЕ ПОДГРУЖАЮТ ЗАЯВКИ С САЙТА. \r\n\r\nХОСТИНГ ЯВЛЯЕТСЯ НЕОТЪЕМЛЕМОЙ ЧАСТЬЮ ЛЮБОГО \r\nВЕБ-ПРОЕКТА. ОТ ХОСТИНГА ЗАВИСИТ СКОРОСТЬ ЗАГРУЗКИ СТРАНИЦ, ПРОИЗВОДИТЕЛЬНОСТЬ САЙТА, БЕЗОПАСНОСТЬ И ЦЕЛОСТНОСТЬ РЕСУРСОВ. НАША КОМПАНИЯ СОТРУДНИЧАЕТ С ВЕДУЩИМИ ХОСТИНГАМИ, КОТОРЫЕ ИДЕАЛЬНО ПОДОЙДУТ ДЛЯ ПРОЕКТОВ НА&NBSP;1С-БИТРИКС И ДРУГИХ CMS.','khosting','19',NULL,NULL,NULL),(76,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,73,'Y','N',500,'Операционные системы',417,48,49,2,'Операционные системы являются своеобразными посредниками между компьютерами и пользователями. Именно они обеспечивают их взаимодействие, а также отвечают за выполнение различных программ. Операционная система –<br>\n это основа компьютера, которая решает 2 основные задачи:<br>\n <br>\n<ul>\n	<li>создает интерфейс между устройствами вычислительной системы и прикладными программами</li>\n	<li>\n	управляет устройствами и рабочими процессами, эффективно распределяя системные ресурсы.</li>\n</ul>\n Самые популярные операционные системы известны каждому, кто работал с компьютером – это линейка продуктов Microsoft. Купить операционную систему&nbsp;Windows для личного и корпоративного использования Вы можете в нашем магазине.<br>','html','ОПЕРАЦИОННЫЕ СИСТЕМЫ\r\nОПЕРАЦИОННЫЕ СИСТЕМЫ ЯВЛЯЮТСЯ СВОЕОБРАЗНЫМИ \r\nПОСРЕДНИКАМИ МЕЖДУ КОМПЬЮТЕРАМИ И ПОЛЬЗОВАТЕЛЯМИ. ИМЕННО ОНИ ОБЕСПЕЧИВАЮТ ИХ ВЗАИМОДЕЙСТВИЕ, А ТАКЖЕ ОТВЕЧАЮТ ЗА ВЫПОЛНЕНИЕ РАЗЛИЧНЫХ ПРОГРАММ. ОПЕРАЦИОННАЯ СИСТЕМА –\r\nЭТО ОСНОВА КОМПЬЮТЕРА, КОТОРАЯ РЕШАЕТ 2 \r\nОСНОВНЫЕ ЗАДАЧИ:\r\n\r\n\r\n\r\n- СОЗДАЕТ ИНТЕРФЕЙС МЕЖДУ УСТРОЙСТВАМИ \r\nВЫЧИСЛИТЕЛЬНОЙ СИСТЕМЫ И ПРИКЛАДНЫМИ ПРОГРАММАМИ \r\n- УПРАВЛЯЕТ УСТРОЙСТВАМИ И РАБОЧИМИ ПРОЦЕССАМИ, \r\nЭФФЕКТИВНО РАСПРЕДЕЛЯЯ СИСТЕМНЫЕ РЕСУРСЫ. САМЫЕ ПОПУЛЯРНЫЕ ОПЕРАЦИОННЫЕ СИСТЕМЫ ИЗВЕСТНЫ КАЖДОМУ, КТО РАБОТАЛ С КОМПЬЮТЕРОМ – ЭТО ЛИНЕЙКА ПРОДУКТОВ MICROSOFT. КУПИТЬ ОПЕРАЦИОННУЮ СИСТЕМУ&NBSP;WINDOWS ДЛЯ ЛИЧНОГО И КОРПОРАТИВНОГО ИСПОЛЬЗОВАНИЯ ВЫ МОЖЕТЕ В НАШЕМ МАГАЗИНЕ.','operatsionnye-sistemy','425',NULL,NULL,NULL),(77,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,73,'Y','N',500,'Продукты 1С',418,50,51,2,'Требования бизнеса и законодательства постоянно меняются, поэтому нужна программа учета, который сможет быстро перенастроиться. Продукты 1С автоматизируют управленческий, бухгалтерский и другие виды учета в бизнесе любого масштаба. <br>\n <br>\n Прикладные решения 1С отличаются высокими темпами внедрения, в том числе поэтапной интеграции. Это обеспечивается прогрессивной архитектурой продукции – единой технологической платформой, на которой настраиваются решения.<br>\n <br>\n 1С легко адаптируется к условиям конкретного предприятия: вы можете централизовано управлять предприятием и оперативно вносить изменения. Приобретая у нас продукцию 1С вы получаете качественный лицензионный продукт для структурированной работы и точной отчетности.','html','ПРОДУКТЫ 1С\r\nТРЕБОВАНИЯ БИЗНЕСА И ЗАКОНОДАТЕЛЬСТВА \r\nПОСТОЯННО МЕНЯЮТСЯ, ПОЭТОМУ НУЖНА ПРОГРАММА УЧЕТА, КОТОРЫЙ СМОЖЕТ БЫСТРО ПЕРЕНАСТРОИТЬСЯ. ПРОДУКТЫ 1С АВТОМАТИЗИРУЮТ УПРАВЛЕНЧЕСКИЙ, БУХГАЛТЕРСКИЙ И ДРУГИЕ ВИДЫ УЧЕТА В БИЗНЕСЕ ЛЮБОГО МАСШТАБА. \r\n\r\nПРИКЛАДНЫЕ РЕШЕНИЯ 1С ОТЛИЧАЮТСЯ ВЫСОКИМИ \r\nТЕМПАМИ ВНЕДРЕНИЯ, В ТОМ ЧИСЛЕ ПОЭТАПНОЙ ИНТЕГРАЦИИ. ЭТО ОБЕСПЕЧИВАЕТСЯ ПРОГРЕССИВНОЙ АРХИТЕКТУРОЙ ПРОДУКЦИИ – ЕДИНОЙ ТЕХНОЛОГИЧЕСКОЙ ПЛАТФОРМОЙ, НА КОТОРОЙ НАСТРАИВАЮТСЯ РЕШЕНИЯ.\r\n\r\n1С ЛЕГКО АДАПТИРУЕТСЯ К УСЛОВИЯМ КОНКРЕТНОГО \r\nПРЕДПРИЯТИЯ: ВЫ МОЖЕТЕ ЦЕНТРАЛИЗОВАНО УПРАВЛЯТЬ ПРЕДПРИЯТИЕМ И ОПЕРАТИВНО ВНОСИТЬ ИЗМЕНЕНИЯ. ПРИОБРЕТАЯ У НАС ПРОДУКЦИЮ 1С ВЫ ПОЛУЧАЕТЕ КАЧЕСТВЕННЫЙ ЛИЦЕНЗИОННЫЙ ПРОДУКТ ДЛЯ СТРУКТУРИРОВАННОЙ РАБОТЫ И ТОЧНОЙ ОТЧЕТНОСТИ.','produkty-1s','424',NULL,419,NULL),(78,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Системы безопасности',420,53,58,1,'Компания «Олл Корп» предлагает автоматизацию защиты вашего объекта. С помощью видеонаблюдения и контроля доступа к сооружениям мы обеспечиваем безопасность внешнего и сохранность внутреннего устройства объекта. Вы можете дистанционно управлять системой защиты и контролировать рабочий процесс в организации.<br>\n<br>\nМы разрабатываем индивидуальные проекты и создаем комплексные системы безопасности, чтобы избежать всех возможных угроз. Наши инженеры устанавливают оборудование за 1 день, поэтому вы сразу сможете использовать предоставленную систему.','html','СИСТЕМЫ БЕЗОПАСНОСТИ\r\nКОМПАНИЯ «ОЛЛ КОРП» ПРЕДЛАГАЕТ АВТОМАТИЗАЦИЮ \r\nЗАЩИТЫ ВАШЕГО ОБЪЕКТА. С ПОМОЩЬЮ ВИДЕОНАБЛЮДЕНИЯ И КОНТРОЛЯ ДОСТУПА К СООРУЖЕНИЯМ МЫ ОБЕСПЕЧИВАЕМ БЕЗОПАСНОСТЬ ВНЕШНЕГО И СОХРАННОСТЬ ВНУТРЕННЕГО УСТРОЙСТВА ОБЪЕКТА. ВЫ МОЖЕТЕ ДИСТАНЦИОННО УПРАВЛЯТЬ СИСТЕМОЙ ЗАЩИТЫ И КОНТРОЛИРОВАТЬ РАБОЧИЙ ПРОЦЕСС В ОРГАНИЗАЦИИ.\r\n\r\nМЫ РАЗРАБАТЫВАЕМ ИНДИВИДУАЛЬНЫЕ ПРОЕКТЫ \r\nИ СОЗДАЕМ КОМПЛЕКСНЫЕ СИСТЕМЫ БЕЗОПАСНОСТИ, ЧТОБЫ ИЗБЕЖАТЬ ВСЕХ ВОЗМОЖНЫХ УГРОЗ. НАШИ ИНЖЕНЕРЫ УСТАНАВЛИВАЮТ ОБОРУДОВАНИЕ ЗА 1 ДЕНЬ, ПОЭТОМУ ВЫ СРАЗУ СМОЖЕТЕ ИСПОЛЬЗОВАТЬ ПРЕДОСТАВЛЕННУЮ СИСТЕМУ.','sistemy-bezopasnosti','410',NULL,NULL,NULL),(79,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,78,'Y','N',500,'Видеонаблюдение',421,54,55,2,'Перед покупкой системы видеонаблюдения четко сформулируйте задачу, которую вы перед ней поставите. Помните, что у каждой видеокамеры есть ограниченный угол обзора и разное качество съемки днем и ночью. Компания «Олл Корп» устанавливает камеры высокого разрешения в помещениях и на придомовых территориях. Стоимость системы зависит от комплектации и возможности ночной съемки.','html','ВИДЕОНАБЛЮДЕНИЕ\r\nПЕРЕД ПОКУПКОЙ СИСТЕМЫ ВИДЕОНАБЛЮДЕНИЯ \r\nЧЕТКО СФОРМУЛИРУЙТЕ ЗАДАЧУ, КОТОРУЮ ВЫ ПЕРЕД НЕЙ ПОСТАВИТЕ. ПОМНИТЕ, ЧТО У КАЖДОЙ ВИДЕОКАМЕРЫ ЕСТЬ ОГРАНИЧЕННЫЙ УГОЛ ОБЗОРА И РАЗНОЕ КАЧЕСТВО СЪЕМКИ ДНЕМ И НОЧЬЮ. КОМПАНИЯ «ОЛЛ КОРП» УСТАНАВЛИВАЕТ КАМЕРЫ ВЫСОКОГО РАЗРЕШЕНИЯ В ПОМЕЩЕНИЯХ И НА ПРИДОМОВЫХ ТЕРРИТОРИЯХ. СТОИМОСТЬ СИСТЕМЫ ЗАВИСИТ ОТ КОМПЛЕКТАЦИИ И ВОЗМОЖНОСТИ НОЧНОЙ СЪЕМКИ.','videonablyudenie','417',NULL,NULL,NULL),(80,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,78,'Y','N',500,'Контроль доступа',422,56,57,2,'Системы контроля доступом ограничивают посещение защищенной территории. Чаще всего устанавливаются в офисах, бизнес-центрах, образовательных учреждениях, промышленных предприятиях, парковках, частных домах и гостиницах. Если вы хотите обезопасить территорию от посторонних, рекомендуем интегрировать систему контроля доступом с видеонаблюдением и другими составляющими комплекса безопасности.','html','КОНТРОЛЬ ДОСТУПА\r\nСИСТЕМЫ КОНТРОЛЯ ДОСТУПОМ ОГРАНИЧИВАЮТ \r\nПОСЕЩЕНИЕ ЗАЩИЩЕННОЙ ТЕРРИТОРИИ. ЧАЩЕ ВСЕГО УСТАНАВЛИВАЮТСЯ В ОФИСАХ, БИЗНЕС-ЦЕНТРАХ, ОБРАЗОВАТЕЛЬНЫХ УЧРЕЖДЕНИЯХ, ПРОМЫШЛЕННЫХ ПРЕДПРИЯТИЯХ, ПАРКОВКАХ, ЧАСТНЫХ ДОМАХ И ГОСТИНИЦАХ. ЕСЛИ ВЫ ХОТИТЕ ОБЕЗОПАСИТЬ ТЕРРИТОРИЮ ОТ ПОСТОРОННИХ, РЕКОМЕНДУЕМ ИНТЕГРИРОВАТЬ СИСТЕМУ КОНТРОЛЯ ДОСТУПОМ С ВИДЕОНАБЛЮДЕНИЕМ И ДРУГИМИ СОСТАВЛЯЮЩИМИ КОМПЛЕКСА БЕЗОПАСНОСТИ.','kontrol-dostupa','416',NULL,NULL,NULL),(81,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Системы вентиляции',423,59,64,1,'<p>\n	 Вентиляционные агрегаты обеспечивают в помещении приток очищенного воздуха комфортной температуры. Если вы планируете расположить аппарат в спальне или кабинете, то обратите внимание на характеристики «шума». Также тщательно продумайте место в комнате для агрегата, чтобы прямые потоки воздуха не попадали на вас и неустойчивые к температурным изменениям предметы.\n</p>\n <br>\n <br>','html','СИСТЕМЫ ВЕНТИЛЯЦИИ\r\nВЕНТИЛЯЦИОННЫЕ АГРЕГАТЫ ОБЕСПЕЧИВАЮТ \r\nВ ПОМЕЩЕНИИ ПРИТОК ОЧИЩЕННОГО ВОЗДУХА КОМФОРТНОЙ ТЕМПЕРАТУРЫ. ЕСЛИ ВЫ ПЛАНИРУЕТЕ РАСПОЛОЖИТЬ АППАРАТ В СПАЛЬНЕ ИЛИ КАБИНЕТЕ, ТО ОБРАТИТЕ ВНИМАНИЕ НА ХАРАКТЕРИСТИКИ «ШУМА». ТАКЖЕ ТЩАТЕЛЬНО ПРОДУМАЙТЕ МЕСТО В КОМНАТЕ ДЛЯ АГРЕГАТА, ЧТОБЫ ПРЯМЫЕ ПОТОКИ ВОЗДУХА НЕ ПОПАДАЛИ НА ВАС И НЕУСТОЙЧИВЫЕ К ТЕМПЕРАТУРНЫМ ИЗМЕНЕНИЯМ ПРЕДМЕТЫ.','sistemy-ventilyatsii1','409',NULL,NULL,NULL),(82,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,81,'Y','N',500,'Воздуховоды',424,60,61,2,'Представляем широкий ассортимент воздуховодов для создания систем вентиляции. С их помощью из помещения удаляется загрязненный воздух и обеспечивается приток свежего. От качества воздуховодов зависит эффективность всего процесса вентилирования. В нашем каталоге вы найдете гибкие и прямые воздуховоды, а также комплектующие к ним.','html','ВОЗДУХОВОДЫ\r\nПРЕДСТАВЛЯЕМ ШИРОКИЙ АССОРТИМЕНТ ВОЗДУХОВОДОВ \r\nДЛЯ СОЗДАНИЯ СИСТЕМ ВЕНТИЛЯЦИИ. С ИХ ПОМОЩЬЮ ИЗ ПОМЕЩЕНИЯ УДАЛЯЕТСЯ ЗАГРЯЗНЕННЫЙ ВОЗДУХ И ОБЕСПЕЧИВАЕТСЯ ПРИТОК СВЕЖЕГО. ОТ КАЧЕСТВА ВОЗДУХОВОДОВ ЗАВИСИТ ЭФФЕКТИВНОСТЬ ВСЕГО ПРОЦЕССА ВЕНТИЛИРОВАНИЯ. В НАШЕМ КАТАЛОГЕ ВЫ НАЙДЕТЕ ГИБКИЕ И ПРЯМЫЕ ВОЗДУХОВОДЫ, А ТАКЖЕ КОМПЛЕКТУЮЩИЕ К НИМ.','vozdukhovody','466',NULL,NULL,NULL),(83,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,81,'Y','N',500,'Комплектующие',425,62,63,2,'В этом разделе вы найдете оборудование, которое обеспечит систему вентиляции полным функционалом и дополнительной защитой. Не стоит пренебрегать комплектующими товарами – они продлевают срок эксплуатации системы вентиляции и повышают эффективность ее работы.','html','КОМПЛЕКТУЮЩИЕ\r\nВ ЭТОМ РАЗДЕЛЕ ВЫ НАЙДЕТЕ ОБОРУДОВАНИЕ, \r\nКОТОРОЕ ОБЕСПЕЧИТ СИСТЕМУ ВЕНТИЛЯЦИИ ПОЛНЫМ ФУНКЦИОНАЛОМ И ДОПОЛНИТЕЛЬНОЙ ЗАЩИТОЙ. НЕ СТОИТ ПРЕНЕБРЕГАТЬ КОМПЛЕКТУЮЩИМИ ТОВАРАМИ – ОНИ ПРОДЛЕВАЮТ СРОК ЭКСПЛУАТАЦИИ СИСТЕМЫ ВЕНТИЛЯЦИИ И ПОВЫШАЮТ ЭФФЕКТИВНОСТЬ ЕЕ РАБОТЫ.','komplektuyushchie','465',NULL,NULL,NULL),(84,'2026-06-04 12:35:44',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',500,'Стройматериалы',426,65,74,1,'<p>\n	 Если вы задумали ремонт квартиры или строительство загородного дома, то покупка строительных материалов, которых потребуется немало, станет один из первых шагов к качественному результату. Походы по строительным рынкам и магазинам только отнимут ваше время, поэтому купить стройматериалы в интернет-магазине – это выгодное решение. У вас есть возможность посчитать расходы, сравнить товары и выбрать способ доставки.\n</p>\n<p>\n	 В компании «Олл Корп» представлены товары для любого этапа строительства – от создания каркаса дома до отделочных работ. Наш call-центр работает с 10:00 до 19:00 и операторы всегда готовы проконсультировать вас по вопросам выбора.\n</p>\n <br>\n <br>','html','СТРОЙМАТЕРИАЛЫ\r\nЕСЛИ ВЫ ЗАДУМАЛИ РЕМОНТ КВАРТИРЫ ИЛИ СТРОИТЕЛЬСТВО \r\nЗАГОРОДНОГО ДОМА, ТО ПОКУПКА СТРОИТЕЛЬНЫХ МАТЕРИАЛОВ, КОТОРЫХ ПОТРЕБУЕТСЯ НЕМАЛО, СТАНЕТ ОДИН ИЗ ПЕРВЫХ ШАГОВ К КАЧЕСТВЕННОМУ РЕЗУЛЬТАТУ. ПОХОДЫ ПО СТРОИТЕЛЬНЫМ РЫНКАМ И МАГАЗИНАМ ТОЛЬКО ОТНИМУТ ВАШЕ ВРЕМЯ, ПОЭТОМУ КУПИТЬ СТРОЙМАТЕРИАЛЫ В ИНТЕРНЕТ-МАГАЗИНЕ – ЭТО ВЫГОДНОЕ РЕШЕНИЕ. У ВАС ЕСТЬ ВОЗМОЖНОСТЬ ПОСЧИТАТЬ РАСХОДЫ, СРАВНИТЬ ТОВАРЫ И ВЫБРАТЬ СПОСОБ ДОСТАВКИ. \r\n\r\nВ КОМПАНИИ «ОЛЛ КОРП» ПРЕДСТАВЛЕНЫ ТОВАРЫ \r\nДЛЯ ЛЮБОГО ЭТАПА СТРОИТЕЛЬСТВА – ОТ СОЗДАНИЯ КАРКАСА ДОМА ДО ОТДЕЛОЧНЫХ РАБОТ. НАШ CALL-ЦЕНТР РАБОТАЕТ С 10:00 ДО 19:00 И ОПЕРАТОРЫ ВСЕГДА ГОТОВЫ ПРОКОНСУЛЬТИРОВАТЬ ВАС ПО ВОПРОСАМ ВЫБОРА.','stroymaterialy','407',NULL,NULL,NULL),(85,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,84,'Y','N',500,'Газоны',427,66,67,2,'Предоставляем услуги по укладке газонов и созданию ландшафтного дизайна. Рулонные газоны устойчивы ко всем погодным условиям и защищены от истирания. Мы сами выращиваем газон, чтобы контролировать процесс и продавать только качественное озеленение участка. Если вы хотите большего, чем зеленый газон, то советуем обратиться к нашим ландшафтным дизайнерам. Они подберут для вас гармоничное сочетание зеленых насаждений, каменных садов и архитектурных элементов.Компания «Олл Корп» поможет окружить вас красотой на десятки лет.','html','ГАЗОНЫ\r\nПРЕДОСТАВЛЯЕМ УСЛУГИ ПО УКЛАДКЕ ГАЗОНОВ \r\nИ СОЗДАНИЮ ЛАНДШАФТНОГО ДИЗАЙНА. РУЛОННЫЕ ГАЗОНЫ УСТОЙЧИВЫ КО ВСЕМ ПОГОДНЫМ УСЛОВИЯМ И ЗАЩИЩЕНЫ ОТ ИСТИРАНИЯ. МЫ САМИ ВЫРАЩИВАЕМ ГАЗОН, ЧТОБЫ КОНТРОЛИРОВАТЬ ПРОЦЕСС И ПРОДАВАТЬ ТОЛЬКО КАЧЕСТВЕННОЕ ОЗЕЛЕНЕНИЕ УЧАСТКА. ЕСЛИ ВЫ ХОТИТЕ БОЛЬШЕГО, ЧЕМ ЗЕЛЕНЫЙ ГАЗОН, ТО СОВЕТУЕМ ОБРАТИТЬСЯ К НАШИМ ЛАНДШАФТНЫМ ДИЗАЙНЕРАМ. ОНИ ПОДБЕРУТ ДЛЯ ВАС ГАРМОНИЧНОЕ СОЧЕТАНИЕ ЗЕЛЕНЫХ НАСАЖДЕНИЙ, КАМЕННЫХ САДОВ И АРХИТЕКТУРНЫХ ЭЛЕМЕНТОВ.КОМПАНИЯ «ОЛЛ КОРП» ПОМОЖЕТ ОКРУЖИТЬ ВАС КРАСОТОЙ НА ДЕСЯТКИ ЛЕТ.','gazony','420',NULL,NULL,NULL),(86,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,84,'Y','N',500,'Изделия из ДПК',428,68,69,2,'Древесно-полимерный композит – это материал, в котором смешаны древесина и мономеры. Такое смешение позволяет ДПК быть устойчивым к насекомым, плесени, солнечному воздействию, повышенной влажности и рассыханию. ДПК не нуждается в дезинфицирующей обработке и периодическом уходе. <br>\n <br>\nУже более 150 частных заказчиков и предприятий оценили преимущества цены и качества нашего материала. Компания «Олл Корп» создает доски из ДПК для заборов, ограждений, сайдинга и террас. Данный материал это качественный продукт для отделки, который украсит территорию и продлит срок эксплуатации вашего дома и ближайшей территории.','html','ИЗДЕЛИЯ ИЗ ДПК\r\nДРЕВЕСНО-ПОЛИМЕРНЫЙ КОМПОЗИТ – ЭТО МАТЕРИАЛ, \r\nВ КОТОРОМ СМЕШАНЫ ДРЕВЕСИНА И МОНОМЕРЫ. ТАКОЕ СМЕШЕНИЕ ПОЗВОЛЯЕТ ДПК БЫТЬ УСТОЙЧИВЫМ К НАСЕКОМЫМ, ПЛЕСЕНИ, СОЛНЕЧНОМУ ВОЗДЕЙСТВИЮ, ПОВЫШЕННОЙ ВЛАЖНОСТИ И РАССЫХАНИЮ. ДПК НЕ НУЖДАЕТСЯ В ДЕЗИНФИЦИРУЮЩЕЙ ОБРАБОТКЕ И ПЕРИОДИЧЕСКОМ УХОДЕ. \r\n\r\nУЖЕ БОЛЕЕ 150 ЧАСТНЫХ ЗАКАЗЧИКОВ И ПРЕДПРИЯТИЙ \r\nОЦЕНИЛИ ПРЕИМУЩЕСТВА ЦЕНЫ И КАЧЕСТВА НАШЕГО МАТЕРИАЛА. КОМПАНИЯ «ОЛЛ КОРП» СОЗДАЕТ ДОСКИ ИЗ ДПК ДЛЯ ЗАБОРОВ, ОГРАЖДЕНИЙ, САЙДИНГА И ТЕРРАС. ДАННЫЙ МАТЕРИАЛ ЭТО КАЧЕСТВЕННЫЙ ПРОДУКТ ДЛЯ ОТДЕЛКИ, КОТОРЫЙ УКРАСИТ ТЕРРИТОРИЮ И ПРОДЛИТ СРОК ЭКСПЛУАТАЦИИ ВАШЕГО ДОМА И БЛИЖАЙШЕЙ ТЕРРИТОРИИ.','izdeliya-iz-dpk','451',NULL,NULL,NULL),(87,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,84,'Y','N',500,'Печи, камины, дымоходы',429,70,71,2,'Компания «Олл Корп» осуществляет продажу и монтаж печного оборудования, дымоходов и каминов. Мы работаем с крупнейшими производителями России и Европы, поэтому вы можете быть уверены в качестве продукции. Правильно смонтированная конструкция системы индивидуального отопления эффективно распределит тепло в помещении и продлит срок эксплуатации оборудования. Менеджеры «Олл Корп» помогут подобрать оптимальное обогревающее оборудование для вашего дома, а опытные техники быстро выполнят комплексные и выборочные монтажные работы. Продукция и работа компании «Олл Корп» добавят уюта вашему дому.','html','ПЕЧИ, КАМИНЫ, ДЫМОХОДЫ\r\nКОМПАНИЯ «ОЛЛ КОРП» ОСУЩЕСТВЛЯЕТ ПРОДАЖУ \r\nИ МОНТАЖ ПЕЧНОГО ОБОРУДОВАНИЯ, ДЫМОХОДОВ И КАМИНОВ. МЫ РАБОТАЕМ С КРУПНЕЙШИМИ ПРОИЗВОДИТЕЛЯМИ РОССИИ И ЕВРОПЫ, ПОЭТОМУ ВЫ МОЖЕТЕ БЫТЬ УВЕРЕНЫ В КАЧЕСТВЕ ПРОДУКЦИИ. ПРАВИЛЬНО СМОНТИРОВАННАЯ КОНСТРУКЦИЯ СИСТЕМЫ ИНДИВИДУАЛЬНОГО ОТОПЛЕНИЯ ЭФФЕКТИВНО РАСПРЕДЕЛИТ ТЕПЛО В ПОМЕЩЕНИИ И ПРОДЛИТ СРОК ЭКСПЛУАТАЦИИ ОБОРУДОВАНИЯ. МЕНЕДЖЕРЫ «ОЛЛ КОРП» ПОМОГУТ ПОДОБРАТЬ ОПТИМАЛЬНОЕ ОБОГРЕВАЮЩЕЕ ОБОРУДОВАНИЕ ДЛЯ ВАШЕГО ДОМА, А ОПЫТНЫЕ ТЕХНИКИ БЫСТРО ВЫПОЛНЯТ КОМПЛЕКСНЫЕ И ВЫБОРОЧНЫЕ МОНТАЖНЫЕ РАБОТЫ. ПРОДУКЦИЯ И РАБОТА КОМПАНИИ «ОЛЛ КОРП» ДОБАВЯТ УЮТА ВАШЕМУ ДОМУ.','pechi-kaminy-dymokhody','419',NULL,NULL,NULL),(88,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,84,'Y','N',500,'Черепица',430,72,73,2,'Цементно-песчаная и керамическая черепица производятся из натурального сырья. Среди преимуществ природной черепицы срок эксплуатации более 100 лет, устойчивость к резкой перемене климата и экстремальным температурам, удобство монтажа и пользования. <br>\n <br>\nКомпания «Олл Корп» поставляет черепицу с заводов Европы. Мы предлагаем вам купить черепицу по конкурентной цене с бесплатной доставкой в пределах города. Для расчета черепичной кровли вы можете оставить заявку и наш менеджер поможет вам узнать конечную стоимость.','html','ЧЕРЕПИЦА\r\nЦЕМЕНТНО-ПЕСЧАНАЯ И КЕРАМИЧЕСКАЯ ЧЕРЕПИЦА \r\nПРОИЗВОДЯТСЯ ИЗ НАТУРАЛЬНОГО СЫРЬЯ. СРЕДИ ПРЕИМУЩЕСТВ ПРИРОДНОЙ ЧЕРЕПИЦЫ СРОК ЭКСПЛУАТАЦИИ БОЛЕЕ 100 ЛЕТ, УСТОЙЧИВОСТЬ К РЕЗКОЙ ПЕРЕМЕНЕ КЛИМАТА И ЭКСТРЕМАЛЬНЫМ ТЕМПЕРАТУРАМ, УДОБСТВО МОНТАЖА И ПОЛЬЗОВАНИЯ. \r\n\r\nКОМПАНИЯ «ОЛЛ КОРП» ПОСТАВЛЯЕТ ЧЕРЕПИЦУ \r\nС ЗАВОДОВ ЕВРОПЫ. МЫ ПРЕДЛАГАЕМ ВАМ КУПИТЬ ЧЕРЕПИЦУ ПО КОНКУРЕНТНОЙ ЦЕНЕ С БЕСПЛАТНОЙ ДОСТАВКОЙ В ПРЕДЕЛАХ ГОРОДА. ДЛЯ РАСЧЕТА ЧЕРЕПИЧНОЙ КРОВЛИ ВЫ МОЖЕТЕ ОСТАВИТЬ ЗАЯВКУ И НАШ МЕНЕДЖЕР ПОМОЖЕТ ВАМ УЗНАТЬ КОНЕЧНУЮ СТОИМОСТЬ.','cherepitsa','418',NULL,NULL,NULL),(89,'2026-06-05 12:17:37',1,'2026-05-18 11:27:13',1,41,NULL,'N','N',700,'Дизайнерская мебель',431,79,86,1,'<p>\n	 Коллекция Flow Form от <a href=\"http://theonebureau.ru/\">The One Bureau</a> – это дизайнерская мебель высокого качества, созданная по вдохновению классических европейский форм и с современными скандинавскими тенденциями. Предметы коллекции выполнены из дуба – крепкого и долговечного материала, который отделан шпоном драгоценного американского ореха. Дизайнерская мебель из коллекции Flow Form от The One Bureau не уступает в качестве европейской, но отличается доступной ценой и изысканным оформлением.\n</p>\n<p>\n	 Волнуетесь, что предметы из классической коллекции не впишутся в ваш интерьер? Беспокоиться не о чем: точеные линии в сочетании с мягкими органическими формами дополнят даже самые дерзкие дизайнерские решения. А если вы захотите изменить оттенок мебели, то с помощью тонированного масла мы создадим уникальный окрас, который подойдет для любого интерьера и стиля.\n</p>\n <br>\n <br>','html','ДИЗАЙНЕРСКАЯ МЕБЕЛЬ\r\nКОЛЛЕКЦИЯ FLOW FORM ОТ THE ONE BUREAU [ HTTP://THEONEBUREAU.RU/ ] \r\n– ЭТО ДИЗАЙНЕРСКАЯ МЕБЕЛЬ ВЫСОКОГО КАЧЕСТВА, СОЗДАННАЯ ПО ВДОХНОВЕНИЮ КЛАССИЧЕСКИХ ЕВРОПЕЙСКИЙ ФОРМ И С СОВРЕМЕННЫМИ СКАНДИНАВСКИМИ ТЕНДЕНЦИЯМИ. ПРЕДМЕТЫ КОЛЛЕКЦИИ ВЫПОЛНЕНЫ ИЗ ДУБА – КРЕПКОГО И ДОЛГОВЕЧНОГО МАТЕРИАЛА, КОТОРЫЙ ОТДЕЛАН ШПОНОМ ДРАГОЦЕННОГО АМЕРИКАНСКОГО ОРЕХА. ДИЗАЙНЕРСКАЯ МЕБЕЛЬ ИЗ КОЛЛЕКЦИИ FLOW FORM ОТ THE ONE BUREAU НЕ УСТУПАЕТ В КАЧЕСТВЕ ЕВРОПЕЙСКОЙ, НО ОТЛИЧАЕТСЯ ДОСТУПНОЙ ЦЕНОЙ И ИЗЫСКАННЫМ ОФОРМЛЕНИЕМ. \r\n\r\nВОЛНУЕТЕСЬ, ЧТО ПРЕДМЕТЫ ИЗ КЛАССИЧЕСКОЙ \r\nКОЛЛЕКЦИИ НЕ ВПИШУТСЯ В ВАШ ИНТЕРЬЕР? БЕСПОКОИТЬСЯ НЕ О ЧЕМ: ТОЧЕНЫЕ ЛИНИИ В СОЧЕТАНИИ С МЯГКИМИ ОРГАНИЧЕСКИМИ ФОРМАМИ ДОПОЛНЯТ ДАЖЕ САМЫЕ ДЕРЗКИЕ ДИЗАЙНЕРСКИЕ РЕШЕНИЯ. А ЕСЛИ ВЫ ЗАХОТИТЕ ИЗМЕНИТЬ ОТТЕНОК МЕБЕЛИ, ТО С ПОМОЩЬЮ ТОНИРОВАННОГО МАСЛА МЫ СОЗДАДИМ УНИКАЛЬНЫЙ ОКРАС, КОТОРЫЙ ПОДОЙДЕТ ДЛЯ ЛЮБОГО ИНТЕРЬЕРА И СТИЛЯ.','dizaynerskaya-mebel','476',NULL,NULL,NULL),(90,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,89,'Y','N',500,'Кровати',432,80,81,2,'В удобной, красивой, изысканной кровати человек легко расслабляется и чувствует себя комфортно. Кровати с балдахином из коллекции Flow Form от <a href=\"http://theonebureau.ru/\">The One Bureau</a> отвечают европейскому качеству и создают неповторимый стиль в любой спальне. Прочность, великолепный&nbsp;дизайн&nbsp;и высокий уровень исполнения – отличительные черты кроватей от The One Bureau.<br>\n <br>\nВнешний вид кроватей продуман до мелочей, чтобы  предметы коллекции могли легко вписаться в любой интерьер и гармонировать с мебелью в спальне. Они выполнены в стиле французской классики XVIII века с добавлением современных деталей. Мы учли, форму, цвета, текстуру, мельчайшие элементы декора и создали идеальное ложе для любого человека.','html','КРОВАТИ\r\nВ УДОБНОЙ, КРАСИВОЙ, ИЗЫСКАННОЙ КРОВАТИ \r\nЧЕЛОВЕК ЛЕГКО РАССЛАБЛЯЕТСЯ И ЧУВСТВУЕТ СЕБЯ КОМФОРТНО. КРОВАТИ С БАЛДАХИНОМ ИЗ КОЛЛЕКЦИИ FLOW FORM ОТ THE ONE BUREAU [ HTTP://THEONEBUREAU.RU/ ] ОТВЕЧАЮТ ЕВРОПЕЙСКОМУ КАЧЕСТВУ И СОЗДАЮТ НЕПОВТОРИМЫЙ СТИЛЬ В ЛЮБОЙ СПАЛЬНЕ. ПРОЧНОСТЬ, ВЕЛИКОЛЕПНЫЙ&NBSP;ДИЗАЙН&NBSP;И ВЫСОКИЙ УРОВЕНЬ ИСПОЛНЕНИЯ – ОТЛИЧИТЕЛЬНЫЕ ЧЕРТЫ КРОВАТЕЙ ОТ THE ONE BUREAU.\r\n\r\nВНЕШНИЙ ВИД КРОВАТЕЙ ПРОДУМАН ДО МЕЛОЧЕЙ, \r\nЧТОБЫ ПРЕДМЕТЫ КОЛЛЕКЦИИ МОГЛИ ЛЕГКО ВПИСАТЬСЯ В ЛЮБОЙ ИНТЕРЬЕР И ГАРМОНИРОВАТЬ С МЕБЕЛЬЮ В СПАЛЬНЕ. ОНИ ВЫПОЛНЕНЫ В СТИЛЕ ФРАНЦУЗСКОЙ КЛАССИКИ XVIII ВЕКА С ДОБАВЛЕНИЕМ СОВРЕМЕННЫХ ДЕТАЛЕЙ. МЫ УЧЛИ, ФОРМУ, ЦВЕТА, ТЕКСТУРУ, МЕЛЬЧАЙШИЕ ЭЛЕМЕНТЫ ДЕКОРА И СОЗДАЛИ ИДЕАЛЬНОЕ ЛОЖЕ ДЛЯ ЛЮБОГО ЧЕЛОВЕКА.','krovati','490',NULL,NULL,NULL),(91,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,89,'Y','N',500,'Мебель для гостиной',433,82,83,2,'В гостиной не обойтись без мебели для хранения: стеллажей, комодов и полок. Приятным дополнением к функциональности предметов становится красота и элегантность мебели, качество исполнения и срок службы. Мы предлагаем лаконичную мебель европейского качества по доступным ценам, чтобы вы могли воплотить в жизнь дизайн своей мечты.<br>\n <br>\n Создайте уютное помещение для приятного времяпрепровождения с помощью дизайнерской мебели&nbsp;из коллекции Flow Form от <a href=\"http://theonebureau.ru/\">The One Bureau</a>. Мягкие формы впишутся в любой интерьер, а тонированный шпон из американского дерева сделает стильной даже самую неприметную комнату.&nbsp;','html','МЕБЕЛЬ ДЛЯ ГОСТИНОЙ\r\nВ ГОСТИНОЙ НЕ ОБОЙТИСЬ БЕЗ МЕБЕЛИ ДЛЯ ХРАНЕНИЯ: \r\nСТЕЛЛАЖЕЙ, КОМОДОВ И ПОЛОК. ПРИЯТНЫМ ДОПОЛНЕНИЕМ К ФУНКЦИОНАЛЬНОСТИ ПРЕДМЕТОВ СТАНОВИТСЯ КРАСОТА И ЭЛЕГАНТНОСТЬ МЕБЕЛИ, КАЧЕСТВО ИСПОЛНЕНИЯ И СРОК СЛУЖБЫ. МЫ ПРЕДЛАГАЕМ ЛАКОНИЧНУЮ МЕБЕЛЬ ЕВРОПЕЙСКОГО КАЧЕСТВА ПО ДОСТУПНЫМ ЦЕНАМ, ЧТОБЫ ВЫ МОГЛИ ВОПЛОТИТЬ В ЖИЗНЬ ДИЗАЙН СВОЕЙ МЕЧТЫ.\r\n\r\nСОЗДАЙТЕ УЮТНОЕ ПОМЕЩЕНИЕ ДЛЯ ПРИЯТНОГО \r\nВРЕМЯПРЕПРОВОЖДЕНИЯ С ПОМОЩЬЮ ДИЗАЙНЕРСКОЙ МЕБЕЛИ&NBSP;ИЗ КОЛЛЕКЦИИ FLOW FORM ОТ THE ONE BUREAU [ HTTP://THEONEBUREAU.RU/ ] . МЯГКИЕ ФОРМЫ ВПИШУТСЯ В ЛЮБОЙ ИНТЕРЬЕР, А ТОНИРОВАННЫЙ ШПОН ИЗ АМЕРИКАНСКОГО ДЕРЕВА СДЕЛАЕТ СТИЛЬНОЙ ДАЖЕ САМУЮ НЕПРИМЕТНУЮ КОМНАТУ.&NBSP;','mebel-dlya-gostinoy','492',NULL,NULL,NULL),(92,'2026-05-18 11:27:13',1,'2026-05-18 11:27:13',1,41,89,'Y','N',500,'Мебель для спальни',434,84,85,2,'Встречайте и провожайте день радостно с дизайнерской коллекцией мебели для спальни Flow Form от <a href=\"http://theonebureau.ru/\">The One Bureau</a>. Функциональные и красивые прикроватные тумбы европейского качества дополнят любую спальню и помогут вам полноценно отдохнуть. Предметы коллекции способны превратить самое обыкновенное помещение в уютную и атмосферную комнату.<br>\n <br>\n Чтобы предметы коллекции идеально вписались в любой интерьер мы добиваемся самых интересных оттенков, покрывая драгоценный американский шпон тонированным маслом. Выберите свой цвет и создайте уникальный стиль спальной комнаты.&nbsp;Используйте прикроватные тумбы для создания ярких акцентов или гармонии между направлениями в интерьере.','html','МЕБЕЛЬ ДЛЯ СПАЛЬНИ\r\nВСТРЕЧАЙТЕ И ПРОВОЖАЙТЕ ДЕНЬ РАДОСТНО \r\nС ДИЗАЙНЕРСКОЙ КОЛЛЕКЦИЕЙ МЕБЕЛИ ДЛЯ СПАЛЬНИ FLOW FORM ОТ THE ONE BUREAU [ HTTP://THEONEBUREAU.RU/ ] . ФУНКЦИОНАЛЬНЫЕ И КРАСИВЫЕ ПРИКРОВАТНЫЕ ТУМБЫ ЕВРОПЕЙСКОГО КАЧЕСТВА ДОПОЛНЯТ ЛЮБУЮ СПАЛЬНЮ И ПОМОГУТ ВАМ ПОЛНОЦЕННО ОТДОХНУТЬ. ПРЕДМЕТЫ КОЛЛЕКЦИИ СПОСОБНЫ ПРЕВРАТИТЬ САМОЕ ОБЫКНОВЕННОЕ ПОМЕЩЕНИЕ В УЮТНУЮ И АТМОСФЕРНУЮ КОМНАТУ.\r\n\r\nЧТОБЫ ПРЕДМЕТЫ КОЛЛЕКЦИИ ИДЕАЛЬНО ВПИСАЛИСЬ \r\nВ ЛЮБОЙ ИНТЕРЬЕР МЫ ДОБИВАЕМСЯ САМЫХ ИНТЕРЕСНЫХ ОТТЕНКОВ, ПОКРЫВАЯ ДРАГОЦЕННЫЙ АМЕРИКАНСКИЙ ШПОН ТОНИРОВАННЫМ МАСЛОМ. ВЫБЕРИТЕ СВОЙ ЦВЕТ И СОЗДАЙТЕ УНИКАЛЬНЫЙ СТИЛЬ СПАЛЬНОЙ КОМНАТЫ.&NBSP;ИСПОЛЬЗУЙТЕ ПРИКРОВАТНЫЕ ТУМБЫ ДЛЯ СОЗДАНИЯ ЯРКИХ АКЦЕНТОВ ИЛИ ГАРМОНИИ МЕЖДУ НАПРАВЛЕНИЯМИ В ИНТЕРЬЕРЕ.','mebel-dlya-spalni','491',NULL,NULL,NULL),(93,'2026-06-08 15:22:31',1,'2026-06-05 11:18:53',1,41,NULL,'Y','Y',500,'Корзины',631,15,16,1,'','text','КОРЗИНЫ\r\n','baskets',NULL,NULL,NULL,NULL),(94,'2026-06-08 15:24:03',1,'2026-06-05 12:07:59',1,41,NULL,'Y','Y',500,'Экраны',632,77,78,1,'','text','ЭКРАНЫ\r\n','shield',NULL,NULL,NULL,NULL),(95,'2026-06-11 12:21:00',1,'2026-06-05 12:08:31',1,41,NULL,'Y','Y',500,'Короба',635,17,18,1,'','text','КОРОБА\r\n','pannier',NULL,NULL,NULL,NULL),(96,'2026-06-24 10:25:38',1,'2026-06-05 12:08:55',1,41,NULL,'Y','Y',500,'Кронштейны',769,19,20,1,'','text','КРОНШТЕЙНЫ\r\n','bracket',NULL,NULL,NULL,NULL),(97,'2026-06-08 15:20:58',1,'2026-06-05 12:09:30',1,41,NULL,'Y','Y',500,'Фасадные кассеты',629,75,76,1,'','text','ФАСАДНЫЕ КАССЕТЫ\r\n','facadecassettes',NULL,NULL,NULL,NULL),(98,'2026-06-11 12:20:50',1,'2026-06-05 12:10:01',1,41,NULL,'Y','Y',500,'Отливы',634,41,42,1,'','text','ОТЛИВЫ\r\n','lowtide',NULL,NULL,NULL,NULL),(99,'2026-06-08 15:16:45',1,'2026-06-05 12:10:21',1,41,NULL,'Y','Y',500,'Капельник',626,11,12,1,'','text','КАПЕЛЬНИК\r\n','kapelnik',NULL,NULL,NULL,NULL),(100,'2026-06-24 12:52:09',1,'2026-06-05 12:11:19',1,40,NULL,'Y','Y',500,'Лазерная резка металла ',692,9,10,1,'<div>\r\n	 Ралмастер производитель изделий из металла с собственным цехом и современным ЧПУ оборудованием в Московской области. Выполняем лазерную резку металла, раскрой листового металла, гибку металла и труб, сварку, зачистку и порошковую покраску. Работаем по чертежам, эскизам, размерам и техническому заданию заказчика.\r\n</div>\r\n<br>','html','ЛАЗЕРНАЯ РЕЗКА МЕТАЛЛА \r\nРАЛМАСТЕР ПРОИЗВОДИТЕЛЬ ИЗДЕЛИЙ ИЗ МЕТАЛЛА \r\nС СОБСТВЕННЫМ ЦЕХОМ И СОВРЕМЕННЫМ ЧПУ ОБОРУДОВАНИЕМ В МОСКОВСКОЙ ОБЛАСТИ. ВЫПОЛНЯЕМ ЛАЗЕРНУЮ РЕЗКУ МЕТАЛЛА, РАСКРОЙ ЛИСТОВОГО МЕТАЛЛА, ГИБКУ МЕТАЛЛА И ТРУБ, СВАРКУ, ЗАЧИСТКУ И ПОРОШКОВУЮ ПОКРАСКУ. РАБОТАЕМ ПО ЧЕРТЕЖАМ, ЭСКИЗАМ, РАЗМЕРАМ И ТЕХНИЧЕСКОМУ ЗАДАНИЮ ЗАКАЗЧИКА.','laser-cutting',NULL,NULL,NULL,NULL),(101,'2026-06-24 12:14:53',1,'2026-06-05 12:11:51',1,40,NULL,'Y','Y',500,'Гибка металла',691,5,6,1,'<h1>Гибка металла по чертежам</h1>\r\n<p>\r\n	<br>\r\n	 Для вас можем изготовить:\r\n</p>\r\n<div>\r\n	— Отливы<br>\r\n	 — Откосы<br>\r\n	 — Аквилоны<br>\r\n	 — Нащельники<br>\r\n	 — Парапеты<br>\r\n	 — Уголки<br>\r\n	 — Капельники<br>\r\n	 — Козырьки<br>\r\n	 — Планки всех видов<br>\r\n	 — Конек любой формы<br>\r\n	 — Ендовы<br>\r\n	 — Снегозадержатели<br>\r\n	 — Фасадные кассеты\r\n</div>','html','ГИБКА МЕТАЛЛА\r\nГИБКА МЕТАЛЛА ПО ЧЕРТЕЖАМ \r\n\r\n\r\nДЛЯ ВАС МОЖЕМ ИЗГОТОВИТЬ: \r\n— ОТЛИВЫ\r\n— ОТКОСЫ\r\n— АКВИЛОНЫ\r\n— НАЩЕЛЬНИКИ\r\n— ПАРАПЕТЫ\r\n— УГОЛКИ\r\n— КАПЕЛЬНИКИ\r\n— КОЗЫРЬКИ\r\n— ПЛАНКИ ВСЕХ ВИДОВ\r\n— КОНЕК ЛЮБОЙ ФОРМЫ\r\n— ЕНДОВЫ\r\n— СНЕГОЗАДЕРЖАТЕЛИ\r\n— ФАСАДНЫЕ КАССЕТЫ','metal-bending',NULL,NULL,695,NULL),(102,'2026-06-24 12:55:32',1,'2026-06-05 12:12:22',1,40,NULL,'Y','Y',500,'Сварка',690,19,20,1,'<div>\r\n	Выполняем сварочные работы для изделий с высокой точностью и контролем качества.\r\n</div>','html','СВАРКА\r\nВЫПОЛНЯЕМ СВАРОЧНЫЕ РАБОТЫ ДЛЯ ИЗДЕЛИЙ \r\nС ВЫСОКОЙ ТОЧНОСТЬЮ И КОНТРОЛЕМ КАЧЕСТВА.','laser-welding',NULL,NULL,694,NULL),(104,'2026-06-26 11:51:42',1,'2026-06-11 12:31:43',1,36,NULL,'N','N',500,'ЖК \"СИМВОЛ \"',640,5,6,1,'Декоративные корзины для кондиционеров, по индивидуальному проекту. 2025 год','text','ЖК \"СИМВОЛ \"\r\nДЕКОРАТИВНЫЕ КОРЗИНЫ ДЛЯ КОНДИЦИОНЕРОВ, ПО ИНДИВИДУАЛЬНОМУ ПРОЕКТУ. 2025 ГОД','zhk-simvol',NULL,NULL,NULL,NULL),(105,'2026-06-23 16:46:54',1,'2026-06-11 12:40:27',1,36,NULL,'N','N',500,'ЖК \" Белый град\"',643,3,4,1,'Декоративные корзины для кондиционеров, по индивидуальному проекту. 2025 год','text','ЖК \" БЕЛЫЙ ГРАД\"\r\nДЕКОРАТИВНЫЕ КОРЗИНЫ ДЛЯ КОНДИЦИОНЕРОВ, ПО ИНДИВИДУАЛЬНОМУ ПРОЕКТУ. 2025 ГОД','zhk-belyy-grad',NULL,NULL,NULL,NULL),(106,'2026-06-24 12:55:47',1,'2026-06-18 10:54:12',1,40,NULL,'Y','Y',500,'Сборка металлоконструкции',689,17,18,1,'<h1>Сборка металла конструкции по индивидуальным чертежам</h1>\r\n<div>\r\n <br>\r\n <br>\r\n	 Сборка любых металлоконструкций.\r\n</div>\r\n <br>','html','СБОРКА МЕТАЛЛОКОНСТРУКЦИИ\r\nСБОРКА МЕТАЛЛА КОНСТРУКЦИИ ПО ИНДИВИДУАЛЬНЫМ \r\nЧЕРТЕЖАМ \r\n\r\n\r\nСБОРКА ЛЮБЫХ МЕТАЛЛОКОНСТРУКЦИЙ.','sborka-metallokonstruktsii',NULL,NULL,693,NULL),(107,'2026-06-26 17:08:26',1,'2026-06-25 15:40:13',1,41,NULL,'N','N',500,'Кассета',NULL,13,14,1,'','text','КАССЕТА\r\n','kasseta',NULL,NULL,NULL,NULL);
